        Paragraph('call 可以无限嵌套（栈深度有限），每一层都可以用 setlocal/endlocal 创建独立变量作用域。exit /b 只退出当前层，回到上一层 call 之后继续执行。这是 BAT 实现"函数"的核心机制。', ST_BODY),
        make_code_block(code3_extra_a),
