    code4_extra_a = _build_code([
        '@echo off',
        'setlocal enabledelayedexpansion',
        'echo === 变量作用域传递 ===',
        'echo.',
        'echo --- 默认: 全局变量 ---',
        'set "g_var=全局值"',
        'echo 主程序: g_var=!g_var!',
        'call :TestScope',
        'echo 主程序返回后: g_var=!g_var! (被改了!)',
        'echo.',
        'echo --- setlocal: 隔离变量 ---',
        'echo 调用带 setlocal 的子程序...',
        'call :TestLocalScope',
        'echo 主程序返回后: g_var=!g_var! (保持原值!)',
        'echo.',
        'echo --- 在 setlocal 内用 endlocal & set 传出 ---',
        'echo 调用需要返回值的子程序...',
        'call :CalcSquare 5 result',
        'echo 主程序里: result=!result!',
        'pause',
        'exit /b',
        ':TestScope',
        'set "g_var=被子程序修改了"',
        'exit /b',
        ':TestLocalScope',
        'setlocal',
        'set "g_var=在子程序内修改"',
        'echo 子程序内: g_var=!g_var!',
        'endlocal',
        'exit /b',
        ':CalcSquare',
        'setlocal',
        'set /a n=%~1 * %~1',
        'endlocal & set "%~2=%n%"',
        'exit /b',
    ])
    code4_extra_b = _build_code([
        '@echo off',
        'setlocal enabledelayedexpansion',
        'echo === 数组实现 ===',
        'echo.',
        'echo --- 方法1: set array[n]=v ---',
        'set "fruit[0]=苹果"',
        'set "fruit[1]=香蕉"',
        'set "fruit[2]=橙子"',
        'set "fruit[3]=葡萄"',
        'set "fruit[4]=西瓜"',
        'echo fruit[0]=!fruit[0]!',
        'echo fruit[3]=!fruit[3]!',
        'echo.',
        'echo --- 遍历数组 ---',
        'for /L %%i in (0,1,4) do echo  fruit[%%i]=!fruit[%%i]!',
        'echo.',
        'echo --- 方法2: 带索引的字符串 ---',
        'set "colors=红 橙 黄 绿 蓝 靛 紫"',
        'set "idx=0"',
        'for %%c in (!colors!) do (',
        '    set "color_list[!idx!]=%%c"',
        '    set /a idx+=1',
        ')',
        'echo 彩虹颜色数: !idx!',
        'for /L %%i in (0,1,6) do echo  color_list[%%i]=!color_list[%%i]!',
        'echo.',
        'echo --- 方法3: 关联数组(模拟) ---',
        'set "dict[name]=张三"',
        'set "dict[age]=25"',
        'set "dict[city]=北京"',
        'echo dict[name]=!dict[name]!',
        'echo dict[age]=!dict[age]!',
        'echo.',
        'echo --- 方法4: 数组作为命令行参数 ---',
        'set "myarr=10 20 30 40 50"',
        'call :PrintElements !myarr!',
        'pause',
        'exit /b',
        ':PrintElements',
        'setlocal',
        'set "sum=0"',
        ':loop',
        'if "%~1"=="" goto :done',
        'echo  元素: %~1',
        'set /a sum+=%~1',
        'shift',
        'goto loop',
        ':done',
        'echo 总和: !sum!',
        'endlocal',
        'exit /b',
    ])
    code4_extra_c = _build_code([
        '@echo off',
        'setlocal enabledelayedexpansion',
        'echo === 字符串拼接优化 ===',
        'echo.',
        'echo --- 方法1: 直接用 set ---',
        'set "hello=Hello"',
        'set "world=World"',
        'set "greeting=!hello! !world!"',
        'echo "!greeting!"',
        'echo.',
        'echo --- 方法2: 循环拼接 (高效) ---',
        'set "long_str="',
        'for /L %%i in (1,1,10) do (',
        '    set "long_str=!long_str!line%%i; "',
        ')',
        'echo "!long_str!"',
        'echo.',
        'echo --- 方法3: 用 ^ 跨行拼接 ---',
        'set "multiline=这是一个很长的字符串，^',
        '它可以跨越多行书写，^',
        '用 ^ 作为续行符，^',
        '但最终是一个连续的值。"',
        'echo "!multiline!"',
        'echo.',
        'echo --- 方法4: 字符串替换做拼接 ---',
        'set "s=abcdef"',
        'echo 原始: !s!',
        'echo 前加 X: !s!s!=X!',
        'set "s=!s!012345"',
        'set "s=X!s!"',
        'echo 前加 X 后加 012345: "!s!"',
        'echo.',
        'echo --- 方法5: !var! 性能注意 ---',
        'echo set var=%%var%% 比 set var=!var! 更快',
        'echo 但括号块内必须用 !var!',
        'set "a=123"',
        'set "b=456"',
        'set "c=!a!!b!"',
        'echo "!c!"',
        'pause',
    ])
