        '    if not exist "%%f" (',
        '        echo ^[MISS^] %%f',
        '        set "missing=1"',
        '    ) else (',
        '        echo ^[OK^]   %%f',
        '    )',
        ')',
        'if defined missing echo.',
        'if defined missing echo 有缺失文件！',
        'endlocal',
        'echo.',
        'echo --- 5. 检查文件是否有内容 ---',
