        Paragraph('进阶主题2：文件描述符 3-9 的高级用法', ST_BODY),
        Paragraph('BAT 预留 fd 0-2 做 stdin/stdout/stderr，fd 3-9 是你可以自由使用的。在括号块里把 fd3 绑定到日志文件，块内所有 echo >&3 都自动写日志，块外恢复正常。这是实现日志系统的优雅方案。', ST_BODY),
