    # ---- ex[13] 追加 ----
    code13_extra_a = _build_code([
        '@echo off',
        'setlocal enabledelayedexpansion',
        'echo === 批量 ping + 写 hosts ===',
        'echo.',
        'echo --- 1. 批量 ping 网段 ---',
        'set "subnet=192.168.1"',
        'echo 扫描 %subnet%.1 - %subnet%.254 ...',
        'set "alive=0"',
        'set "dead=0"',
        'for /L %%i in (1,1,254) do (',
        '    ping -n 1 -w 300 %subnet%.%%i >nul 2>nul',
        '    if !errorlevel! equ 0 (',
        '        echo [UP]   %subnet%.%%i',
        '        set /a alive+=1',
        '    ) else (',
        '        set /a dead+=1',
        '    )',
        ')',
        'echo.',
        'echo 存活: !alive! 不可达: !dead!',
        'echo.',
        'echo --- 2. 更高效: 后台并发 ---',
        'echo 用 start /b 同时 ping:',
        'for /L %%i in (1,1,20) do start /b cmd /c "ping -n 1 -w 200 %subnet%.%%i ^| findstr TTL >> alive.txt"',
        'echo 等待扫描...',
        'timeout /t 5 >nul',
        'echo 在线主机:',
        'type alive.txt 2>nul',
        'del alive.txt 2>nul',
        'echo.',
        'echo --- 3. 写 hosts 文件 ---',
        'echo hosts 文件位置: %SystemRoot%\\System32\\drivers\\etc\\hosts',
        'echo 添加条目 (管理员权限):',
        'echo 127.0.0.1 example.com ^>^> %SystemRoot%\\System32\\drivers\\etc\\hosts',
        'echo.',
        'echo 备份 hosts:',
        'copy "%SystemRoot%\\System32\\drivers\\etc\\hosts" hosts_backup.txt',
        'echo.',
        'echo --- 4. 快速编辑 hosts ---',
        'echo notepad %SystemRoot%\\System32\\drivers\\etc\\hosts',
        'echo 或用管理员权限:',
        'echo start "" notepad %SystemRoot%\\System32\\drivers\\etc\\hosts',
        'echo.',
        'echo --- 5. 刷新 DNS 缓存 ---',
        'ipconfig /flushdns',
        'pause',
    ])
    code13_extra_b = _build_code([
        '@echo off',
        'echo === 端口转发 (netsh interface portproxy) ===',
        'echo.',
        'echo --- 1. 基础用法 ---',
        'echo 把本机 8080 转发到内部服务器 80 端口:',
        'echo netsh interface portproxy add v4tov4 listenport=8080 listenaddress=0.0.0.0 connectport=80 connectaddress=192.168.1.100',
        'echo.',
        'echo --- 2. 查看当前转发规则 ---',
        'netsh interface portproxy show all',
        'echo.',
        'echo --- 3. 删除规则 ---',
        'echo netsh interface portproxy delete v4tov4 listenport=8080 listenaddress=0.0.0.0',
        'echo 删除所有:',
        'echo netsh interface portproxy delete v4tov4',
        'echo.',
        'echo --- 4. 实际场景 ---',
        'echo 访问内网 Web 服务 (公司-家庭):',
        'echo netsh interface portproxy add v4tov4 listenport=8080 connectport=80 connectaddress=10.0.0.5',
        'echo 访问内网数据库:',
        'echo netsh interface portproxy add v4tov4 listenport=3307 connectport=3306 connectaddress=10.0.0.10',
        'echo.',
        'echo --- 5. 检查转发是否生效 ---',
        'echo netstat -ano | findstr LISTENING | findstr 8080',
        'echo.',
        'echo --- 6. 持久化 ---',
        'echo 转发规则重启后保留 (存在注册表)',
        'echo HKLM\\SYSTEM\\CurrentControlSet\\Services\\PortProxy\\v4tov4\\tcp',
        'echo.',
        'echo --- 7. 防火墙 ---',
        'echo 需要放行监听端口:',
        'echo netsh advfirewall firewall add rule name="Port Forward 8080" dir=in action=allow protocol=TCP localport=8080',
        'echo.',
        'echo --- 8. 备选方案 ---',
        'echo 临时转发用 PowerShell:',
        'echo $l=New-Object Net.Sockets.TcpListener(8080); ...',
        'echo SSH 隧道也可以: ssh -L 8080:192.168.1.100:80 user@server',
        'pause',
    ])
    code13_extra_c = _build_code([
        '@echo off',
        'echo === 用 netsh dump 备份网络配置 ===',
        'echo.',
        'echo --- 1. netsh dump ---',
        'echo 完整网络配置 dump:',
        'netsh dump > network_backup.txt',
        'echo 已保存到 network_backup.txt',
        'echo 内容预览:',
        'type network_backup.txt',
        'echo.',
        'echo --- 2. 恢复网络配置 ---',
        'echo netsh -f network_backup.txt',
        'echo.',
        'echo --- 3. 导出特定接口配置 ---',
        'echo 导出 IP 配置:',
        'netsh interface ip dump > ip_config.txt',
        'echo 导出接口配置:',
        'netsh interface dump > interface_config.txt',
        'echo 导出 HTTP 代理:',
        'netsh winhttp dump > proxy_config.txt',
        'echo.',
        'echo --- 4. 查看当前配置 ---',
        'echo 所有接口:',
        'netsh interface show interface',
        'echo.',
        'echo IP 地址:',
        'netsh interface ip show config',
        'echo.',
        'echo 路由表:',
        'netsh interface ipv4 show routes',
        'echo.',
        'echo DNS 服务器:',
        'netsh interface ipv4 show dnsservers',
        'echo.',
        'echo --- 5. 一键备份脚本 ---',
        '(',
        '    @echo off',
        '    set "out=net_backup_%date:~0,4%%date:~5,2%%date:~8,2%"',
        '    mkdir "%out%"',
        '    netsh dump > "%out%\\full.txt"',
        '    netsh interface ip dump > "%out%\\ip.txt"',
        '    netsh interface dump > "%out%\\interface.txt"',
        '    netsh advfirewall dump > "%out%\\firewall.txt"',
        '    echo 网络配置备份完成到 %out%',
        ') > backup_network.bat',
        'echo 已生成 backup_network.bat',
        'echo.',
        'del network_backup.txt ip_config.txt interface_config.txt proxy_config.txt 2>nul',
        'pause',
    ])
    ex[13] = ex[13] + [
        Spacer(1, 15),
        Paragraph('进阶主题1：批量 ping + 写 hosts', ST_BODY),
        Paragraph('批量 ping 用 start /b 并发比 for 循环快几十倍——每个 ping 是独立 cmd 进程。写 hosts 是做静态 DNS 解析的快速方案，特别适合屏蔽广告域名或加速内网访问。ipconfig /flushdns 必须刷新缓存才生效。', ST_BODY),
        make_code_block(code13_extra_a),
        Paragraph('进阶主题2：端口转发（netsh interface portproxy）', ST_BODY),
        Paragraph('portproxy 把一台机器当网络网关。最经典的场景：在家庭电脑上把 localhost:8080 转发到公司内网的 10.0.0.5:80。规则持久化到注册表，重启不丢。别忘了放防火墙。', ST_BODY),
        make_code_block(code13_extra_b),
        Paragraph('进阶主题3：用 netsh dump 备份网络配置', ST_BODY),
        Paragraph('netsh dump 是一键备份所有网络配置的神器。包含接口、IP、路由、防火墙、代理等所有设置。恢复用 netsh -f file.txt。建议每次改网络配置前先 dump 一份。', ST_BODY),
        make_code_block(code13_extra_c),
    ]

    # ---- ex[14] 追加 ----
    code14_extra_a = _build_code([
        '@echo off',
        'setlocal enabledelayedexpansion',
        'echo === ANSI 颜色码全屏绘制 ===',
        'echo (Windows 10 1511+ 默认支持, cmd /? 看版本)',
        'echo.',
        'echo --- 基础颜色 ---',
        'echo ESC = 0x1B = $E in prompt = call :ansi function',
        'echo.',
        'echo 标准方法:',
        'echo 16 种颜色 (黑/蓝/绿/青/红/紫/黄/灰 各深浅两档)',
        'for /L %%i in (30,1,37) do (',
        '    <nul set /p "= [38;5;%%im"',
        '    echo   Color %%i',
        ')',
        'echo.',
        'echo 256 色模式 (38;5;n):',
        'for /L %%i in (16,1,31) do <nul set /p "= [38;5;%%m  ", echo.',
        'echo.',
        'echo --- 真正的 BAT 实现 ---',
        'set "ESC="',
        'for /F %%a in (\'echo $E ^| prompt $E ^& rem\') do set "ESC=%%a"',
        'if not defined ESC (',
        '    for /f "tokens=2 delims=:" %%a in (\'findstr /p /v /a:0a "" "C:\\Windows\\System32\\cmd.exe" 2^>nul\') do set "ESC=%%a"',
        ')',
        'echo 另一个获取 ESC 的方法:',
        'for /f %%a in (\'powershell -Command "[char]27"\') do set "ESC=%%a"',
        'echo ESC 已获取: len=!ESC:len=!',
        'echo.',
        'echo --- 用 ESC 绘制 ---',
        'echo !ESC![32m绿色文本!ESC![0m',
        'echo !ESC![33m黄色文本!ESC![0m',
        'echo !ESC![44;37m蓝底白字!ESC![0m',
        'echo !ESC![1;35m加粗紫色!ESC![0m',
        'echo !ESC![38;2;255;128;0mRGB 橙色!ESC![0m',
        'echo.',
        'echo --- 清屏 ---',
        'echo !ESC![2J!ESC![H  清屏并回到左上角',
        'echo !ESC![s          保存光标位置',
        'echo !ESC![u          恢复光标位置',
        'echo !ESC![10;20H     移动光标到 (10,20)',
        'pause',
    ])
    code14_extra_b = _build_code([
        '@echo off',
        'echo === 用 rundll32 调 Windows API ===',
        'echo.',
        'echo rundll32 调用 DLL 里的函数, 格式:',
        'echo rundll32.exe dllname.dll,functionname parameters',
        'echo.',
        'echo --- 1. 打开控制面板 ---',
        'rundll32.exe shell32.dll,Control_RunDLL',
        'echo.',
        'echo --- 2. 打开文件夹 ---',
        'rundll32.exe shell32.dll,SHHelpShortcuts_RunDLL',
        'rundll32.exe shell32.dll,OpenAs_RunDLL "C:\\Windows\\notepad.exe"',
        'echo.',
        'echo --- 3. 显示关于对话框 ---',
        'rundll32.exe shell32.dll,AboutWindows',
        'rundll32.exe user32.dll,MessageBeep',
        'echo.',
        'echo --- 4. 清空回收站 ---',
        'rundll32.exe shell32.dll,SHEmptyRecycleBin',
        'echo.',
        'echo --- 5. 选择文件夹对话框 ---',
        'rundll32.exe shell32.dll,BrowseForFolder',
        'echo.',
        'echo --- 6. 打开打印机对话框 ---',
        'rundll32.exe shell32.dll,SHShowManagePrinters',
        'echo.',
        'echo --- 7. PowerShell 包装 DLL 调用 (更灵活) ---',
        'echo Add-Type -TypeDefinition ''[DllImport("user32.dll")] public static extern int GetTickCount();''',
        'echo $type.GetTickCount()',
        'echo.',
        'echo --- 8. 更多 rundll32 命令 ---',
        'echo rundll32.exe shell32.dll,RunDLL 打开文件夹浏览器',
        'echo rundll32.exe shlwapi.dll,StatusBarMessage',
        'echo rundll32.exe winspool.drv,PrintProperties',
        'echo.',
        'echo --- 9. rundll32 限制 ---',
        'echo 只能调特定签名的函数 (W entry point)',
        'echo 复杂 DLL 函数用 PowerShell Add-Type',
        'pause',
    ])
    code14_extra_c = _build_code([
        '@echo off',
        'echo === 注册表监控 ===',
        'echo 用 RegNotifyChangeKeyValue via PowerShell:',
        'echo.',
        'echo --- 1. 监控注册表变化 (PowerShell) ---',
        'echo 监控 HKCU\\Software 键的变化:',
        'powershell -Command @\'',
        'Add-Type -TypeDefinition \'',
        'using System;',
        'using System.Runtime.InteropServices;',
        'public class RegMon {',
        '    [DllImport("advapi32.dll")]',
        '    public static extern int RegNotifyChangeKeyValue(IntPtr hKey, bool bWatchSubtree, int dwNotifyFilter, IntPtr hEvent, bool fAsynchronous);',
        '}',
        '\'',
        '$key = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey("Software")',
        '$notifyFilter = 0x00000001 -bor 0x00000002 -bor 0x00000004 -bor 0x00000008',
        'Write-Host "正在监控 HKCU\\Software 变化 (Ctrl+C 退出)..."',
        'while ($true) {',
        '    $result = [RegMon]::RegNotifyChangeKeyValue($key.Handle, $true, $notifyFilter, [IntPtr]::Zero, $false)',
        '    Write-Host "$(Get-Date -Format HH:mm:ss) 检测到变化! 返回码: $result"',
        '}',
        '\'',
        'echo.',
        'echo --- 2. 简单注册表变更快照 ---',
        'echo before.reg:',
        'reg export "HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Run" before.reg /y 2>nul',
        'echo.',
        'echo 现在去添加一个启动项, 然后运行:',
        'echo reg export "HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Run" after.reg',
        'echo fc before.reg after.reg',
        'echo.',
        'echo --- 3. 实时监控脚本 ---',
        '(',
        '    @echo off',
        '    :loop',
        '    reg query "HKLM\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Run" > current.reg 2>nul',
        '    fc /n current.reg last.reg >nul 2>nul',
        '    if errorlevel 1 (',
        '        echo [%time%] 注册表变化!',
        '        fc /n last.reg current.reg',
        '        copy /y current.reg last.reg >nul',
        '    )',
        '    timeout /t 5 >nul',
        '    goto loop',
        ') > watch_reg.bat',
        'echo 已生成 watch_reg.bat 启动注册表监控',
        'echo.',
        'del before.reg 2>nul',
        'pause',
    ])
    ex[14] = ex[14] + [
        Spacer(1, 15),
        Paragraph('进阶主题1：ANSI 颜色码全屏绘制', ST_BODY),
        Paragraph('Windows 10+ 的 cmd.exe 支持 ANSI 转义码。核心难点是获取 ESC (0x1B) 字符，最稳的方案是通过 PowerShell。256 色和真彩色 (38;2;R;G;B) 都支持，ESC[2J ESC[H 是清屏。', ST_BODY),
        make_code_block(code14_extra_a),
        Paragraph('进阶主题2：用 rundll32 调 Windows API', ST_BODY),
        Paragraph('rundll32 可以调用 DLL 里特定签名的导出函数。shell32.dll、user32.dll、shlwapi.dll 里有很多方便的功能——清空回收站、打开控制面板、选择文件夹对话框等。复杂函数用 PowerShell Add-Type。', ST_BODY),
        make_code_block(code14_extra_b),
        Paragraph('进阶主题3：注册表监控（RegNotifyChangeKeyValue via PowerShell）', ST_BODY),
        Paragraph('Windows API RegNotifyChangeKeyValue 可以实时监控注册表变化。BAT 直接调这个 API 很难，但通过 PowerShell Add-Type 声明 P/Invoke 就很简单。简单监控可以用 reg export + fc 做快照差分。', ST_BODY),
        make_code_block(code14_extra_c),
    ]

