        ['F6', '插入 EOF (Z) 字符', '重定向文件结束符'],
        ['F7', '命令历史列表弹窗', '可视化选择历史命令'],
        ['F8', '按前缀搜索历史', '输入 cmd 后 F8 循环匹配'],
        ['F9', '按编号选历史命令', '配合 F7 显示的编号'],
        ['Tab', '自动补全文件/路径', '路径输入利器'],
        ['↑ / ↓', '浏览历史命令（上下条）', '最常用的历史浏览'],
        ['← / →', '光标左右移动', '编辑当前行'],
        ['Home / End', '光标移到行首/行尾', '快速定位'],
        ['Insert', '插入/覆盖模式切换', '编辑长命令行'],
        ['Esc', '清空当前输入行', '打错了重打'],
