        ['传参用 %~N', 'call :func %var1% %var2%', 'call :func "text with spaces"', '~ 自动去引号'],
        ['返回值用 exit /b', ':func ... exit /b 1', 'set "ret=val"; goto :eof', 'errorlevel 更标准'],
        ['局部变量隔离', ':func\n  setlocal\n  set x=1\n  ...\n  endlocal\n  exit /b 0', ':func\n  set x=1', '防止污染外层变量'],
        ['大脚本分模块', '主文件 + call include\\module.bat', '一个 1000 行巨型 BAT', '可维护性大幅提升'],
        ['主流程末尾用 goto :eof', '主流程末尾 goto :eof\n:func ... exit /b 0', '主流程直接 fall-through 到子程序', '避免意外执行子程序'],
        ['避免深层嵌套 call', 'call :a → call :b → call :c', '10 层以上嵌套', 'BAT 栈有限，过深会崩溃'],
