        Paragraph('第 3 章小结', ST_SEC_TITLE),
        Paragraph('本章解决了 BAT 脚本"从一堆命令"升级到"结构化程序"的关键问题——call、goto 和 exit /b 的配合。新手最核心的认知突破是：call :func 后 func 里的 exit /b 只退出子程序，而 goto :eof 从 call 返回；如果没有 call 直接 goto :eof 则结束整个脚本。', ST_BODY),
        Paragraph('表 3-1 总结了 call 和 goto 在 15 个维度上的差异。最重要的三点：call 会记住返回点，goto 不会；call 能传参用 %~N 接收；call 后 errorlevel 可作为返回值。记住这三条就能写清晰的模块化脚本了。', ST_BODY),
        Paragraph('表 3-2 给出了 15 条子程序最佳实践，其中最容易被忽略的是"主流程末尾用 goto :eof"——如果不写 goto :eof，脚本会 fall-through 到下面的子程序标签，第一次运行还好，call 返回后就会接着执行，造成意料外的行为。', ST_BODY),
        Paragraph('模块化框架示例展示了大型脚本的典型组织方式：call :init 初始化 → call :show_menu 菜单循环 → 每个功能一个 call 子程序。日志、备份、恢复、清理、诊断全都拆成独立子程序，改一处不影响别处。', ST_BODY),
        Paragraph('call vs goto 测试脚本对比了 goto 不返回、call 会返回、传参、变量作用域和 errorlevel 返回值五个典型场景。建议读者亲手跑这个脚本并观察输出，比读十页书印象更深。', ST_BODY),
        Paragraph('下一章进入变量的修饰符和环境变量。%~dp0、%~nx1 这些路径修饰符是 BAT 脚本最常用的技巧之一，必须烂熟于心。', ST_BODY),
