        'echo.',
        'echo --- 修饰符分解 ---',
        'echo 完整绝对路径 (!full!',
        'echo 驱动器号  !drive!',
        'echo 目录路径  !dir!',
        'echo 文件主名  !name!',
        'echo 扩展名    !ext!',
        'echo 短路径    !short!',
        'echo 文件属性  !attr!',
        'echo 修改时间  !date!',
        'echo 文件大小  !size! 字节',
        'echo.',
        'echo --- 组合路径 ---',
        'echo 父目录:   !dir!',
        'echo 完整文件名: !name!!ext!',
        'echo URL风格:  file:///C:/example/path',
        'echo 命令风格: "!full!"',
        'echo.',
        'echo --- 路径拼接演示 ---',
        'set "base=C:\\Users\\Harry"',
        'set "relative=Desktop\\test.txt"',
        'for %%P in ("!base!\\!relative!") do echo 拼接结果: %%~fP',
        'echo.',
        'echo --- 存在性检查 ---',
        'if exist "!full!" (',
        '    echo [OK] 路径存在',
        '    if exist "!full!"\\* (',
        '        echo      类型: 目录',
        '    ) else (',
        '        echo      类型: 文件',
        '    )',
        ') else (',
        '    echo [X] 路径不存在',
        ')',
