    # ============ 第7章 追加：文件操作命令对比 + 批处理文件常用扩展名 ============
    code7_extra_d = _build_code([
        '@echo off',
        'setlocal enabledelayedexpansion',
        'echo =============================================',
        'echo   第7章综合实战：文件操作全家桶',
        'echo   copy / xcopy / robocopy / move / del',
        'echo =============================================',
        'echo.',
        'set "src=%temp%\\file_ops_src"',
        'set "dst=%temp%\\file_ops_dst"',
        'rmdir /s /q "!src!" "!dst!" 2>nul',
        'mkdir "!src!" 2>nul',
        'mkdir "!src!\\sub1" 2>nul',
        'mkdir "!src!\\sub2" 2>nul',
        'echo file1 > "!src!\\file1.txt"',
        'echo file2 > "!src!\\file2.txt"',
        'echo file3 > "!src!\\sub1\\file3.txt"',
        'echo file4 > "!src!\\sub2\\file4.dat"',
        'echo 准备好源目录:',
        'dir /b /s "!src!"',
        'echo.',
        'rem === copy ===',
        'echo [1] copy - 单/多文件复制:',
        'copy "!src!\\file1.txt" "!dst!\\" /nfl /ndl /njh /njs /nc /ns 2>nul & echo   copy 完成',
        'echo   内容: & type "!dst!\\file1.txt"',
        'echo.',
        'rem === xcopy ===',
        'echo [2] xcopy - 递归复制整个目录:',
        'xcopy "!src!" "!dst!\\xcopy_copy\\" /e /i /q /y 2>nul & echo   xcopy 完成',
        'dir /b /s "!dst!\\xcopy_copy"',
        'echo.',
        'rem === robocopy ===',
        'echo [3] robocopy - 专业级复制（多线程、断点续传）:',
        'robocopy "!src!" "!dst!\\robocopy_copy" /E /NFL /NDL /NJH /NJS /NC /NS /NP >nul 2>&1',
        'echo   robocopy 完成 (exit code: !errorlevel!)',
        'dir /b /s "!dst!\\robocopy_copy"',
        'echo.',
        'rem === move ===',
        'echo [4] move - 文件移动:',
        'mkdir "!dst!\\move_test" 2>nul',
        'copy "!src!\\file2.txt" "!dst!\\move_test\\" 2>nul',
        'move "!dst!\\move_test\\file2.txt" "!dst!\\moved.txt" >nul 2>&1',
        'echo   move 完成',
        'dir /b "!dst!"',
        'echo.',
        'rem === del ===',
        'echo [5] del - 批量删除:',
        'copy "!src!\\sub1\\file3.txt" "!dst!\\file3.txt" 2>nul',
        'echo   删除前: & dir /b "!dst!\\file3.txt" 2>nul',
        'del /q "!dst!\\file3.txt" 2>nul',
        'echo   删除后: & dir /b "!dst!\\file3.txt" 2>nul & echo    (已删除)',
        'echo.',
        'rem === 清理 ===',
        'rmdir /s /q "!src!" "!dst!"',
        'echo === 文件操作全部演示完毕 ===',
        'pause',
    ])
    code7_extra_e = _build_code([
        '@echo off',
        'setlocal enabledelayedexpansion',
        'echo =============================================',
        'echo   第7章进阶：增量备份脚本（robocopy 版）',
        'echo   只备份变化的文件，保留历史版本',
        'echo =============================================',
        'echo.',
        'set "BACKUP_SRC=%~dp0data"',
        'set "BACKUP_ROOT=%~dp0backups"',
        'set "timestamp=%date:~0,4%%date:~5,2%%date:~8,2%_%time:~0,2%%time:~3,2%"',
        'set "timestamp=!timestamp: =0!"',
        'set "backup_name=backup_!timestamp!"',
        'set "full_dest=!BACKUP_ROOT!\\!backup_name!"',
        'echo 备份源:   !BACKUP_SRC!',
        'echo 备份目标: !full_dest!',
        'mkdir "!BACKUP_SRC!" 2>nul',
        'echo test1 > "!BACKUP_SRC!\\sample.txt"',
        'echo test2 >> "!BACKUP_SRC!\\sample.txt"',
        'echo line1 > "!BACKUP_SRC!\\config.ini"',
        'mkdir "!BACKUP_SRC!\\sub" 2>nul',
        'echo nested > "!BACKUP_SRC!\\sub\\nested.txt"',
        'echo 源文件列表:',
        'dir /b /s "!BACKUP_SRC!"',
        'echo.',
        'robocopy "!BACKUP_SRC!" "!full_dest!" /E /MIR /R:3 /W:5 /MT:8 /NFL /NDL /NJH /NJS /NC /NS /NP',
        'set "rc=!errorlevel!"',
        'if !rc! leq 7 (',
        '    echo.',
        '    echo [OK] 备份成功 (robocopy exit: !rc!)',
        ') else (',
        '    echo.',
        '    echo [FAIL] 备份失败 (robocopy exit: !rc!)',
        ')',
        'echo.',
        'echo === 备份内容 ===',
        'dir /b /s "!full_dest!"',
        'echo.',
        'echo === 保留最近 5 份，删除更早的 ===',
        'set /a keep=5',
        'for /f "skip=!keep! delims=" %%d in (\'dir /ad /b /o-n "!BACKUP_ROOT!"\') do (',
        '    echo   删除旧备份: %%d',
        '    rd /s /q "!BACKUP_ROOT!\\%%d"',
        ')',
        'echo.',
        'echo === 当前备份列表 ===',
        'dir /ad /b "!BACKUP_ROOT!"',
        'echo.',
        'pause',
    ])
    code7_proj = _build_code([
        '@echo off',
        'setlocal enabledelayedexpansion',
        'echo =============================================',
        'echo   第7章项目：批量文件同步工具',
        'echo   双向同步两个目录，支持镜像和合并',
        'echo =============================================',
        'echo.',
        'set /p "source=源目录: "',
        'set /p "target=目标目录: "',
        'if not exist "!source!" echo 源目录不存在 & pause & exit /b 1',
        'if not exist "!target!" mkdir "!target!"',
        'echo.',
        'echo [1] 镜像同步（目标变成源的精确副本）',
        'echo [2] 单向合并（源覆盖目标，保留目标独有文件）',
        'echo [3] 双向合并（两边都复制过去，冲突时覆盖）',
        'set /p "mode=选择模式 [1-3]: "',
        'echo.',
        'if "!mode!"=="1" goto mirror',
        'if "!mode!"=="2" goto oneway',
        'if "!mode!"=="3" goto twoway',
        'goto end',
        ':mirror',
        'echo === 镜像同步 ===',
        'echo 目标将变成源的精确副本（多的删除）',
        'pause',
        'robocopy "!source!" "!target!" /E /MIR /R:2 /W:3 /MT:8',
        'echo 完成 (exit: !errorlevel!)',
        'goto end',
        ':oneway',
        'echo === 单向合并 ===',
        'echo 源中新文件会复制过去，目标独有文件保留',
        'robocopy "!source!" "!target!" /E /R:2 /W:3 /MT:8',
        'echo 完成 (exit: !errorlevel!)',
        'goto end',
        ':twoway',
        'echo === 双向合并 ===',
        'echo 先从源到目标，再从目标到源',
        'echo --- 源 -^> 目标 ---',
        'robocopy "!source!" "!target!" /E /R:2 /W:3 /MT:8',
        'echo --- 目标 -^> 源 ---',
        'robocopy "!target!" "!source!" /E /R:2 /W:3 /MT:8',
        'echo 完成',
        'goto end',
        ':end',
        'echo.',
        'echo === 同步结果对比 ===',
        'echo 源目录文件数: & dir /s /b "!source!" 2>nul | find /c /v ""',
        'echo 目标文件数:   & dir /s /b "!target!" 2>nul | find /c /v ""',
        'pause',
    ])

