        Paragraph('文件操作的"三驾马车"是 copy（简单）、xcopy（中级）、robocopy（专业）。表 7-1 用 15 个维度把它们和 move、del、rd、attrib、fc、replace、tar、certutil 等一网打尽。bat 新脚本一律用 robocopy，别再纠结 xcopy 了。', ST_BODY),
        Paragraph('robocopy 的关键参数：/MIR 镜像同步（会删多余文件！）、/MT:8 8 线程加速、/R:3 /W:5 失败重试 3 次每次等 5 秒、/E 包含空子目录、/NFL /NDL 精简日志。它的退出码 0-7 都算成功（0=没变化，7=有变化且有警告），>=8 才是真正失败。', ST_BODY),
        Paragraph('文件扩展名表列了 19 种脚本/可执行相关后缀。BAT 里最常见的是 .bat 和 .cmd，两者在现代 Windows 上几乎等价；.ps1 PowerShell 脚本可以用 powershell -File script.ps1 从 BAT 里调用；.msi 安装包可以用 msiexec /qn /i package.msi 静默安装。', ST_BODY),
