        ['%~z1', '文件大小（字节）', 'report.txt', '1024', '整数'],
        ['%~$PATH:1', '在 PATH 中搜索', 'ping', 'C:\\Win\\System32\\ping.exe', '唯一要加 PATH:'],
        ['%~dp1', '驱动器+目录', 'C:\\Users\\f.txt', 'C:\\Users\\', '组合修饰符'],
        ['%~nx1', '文件名+后缀', 'report.docx', 'report.docx', '最常用组合'],
        ['%~fs1', '完整短路径', 'report.txt', 'C:\\WD\\REPORT~1.TXT', '兼容旧 API'],
        ['%~ftza1', '全部信息', 'report.txt', 'a-- 1024 11/10/26 C:\\...', '大组合'],
        ['%~dp0', '脚本所在目录', '(自动)', 'C:\\script_dir\\', '几乎每脚本都用'],
        ['%~nx0', '脚本文件名', '(自动)', 'my_script.bat', '日志标题'],
        ['%~f0', '脚本完整路径', '(自动)', 'C:\\WD\\my_script.bat', 'self-reference'],
