        Paragraph('第 8 章小结', ST_SEC_TITLE),
        Paragraph('路径修饰符表把 14 种基础 + 6 种组合全部列清。最核心的几个：%~dp0 脚本目录、%~nx1 文件名、%~f1 完整路径、%~1 去引号。BAT 写脚本的第一条纪律——任何涉及文件路径的操作，先想到能不能用修饰符。', ST_BODY),
        Paragraph('路径拼接对比把 BAT 里常见的 7 种路径拼接方案按可靠性从低到高排序：直接拼（最简但易错）→ %%~fP（BAT 内置首选）→ PowerShell [IO.Path]::Combine（最标准）。记住 BAT 里 %%~fP 会自动规范化 . 和 \\.\\，但不会处理跨盘符相对路径。', ST_BODY),
        Paragraph('路径工具箱项目把 10 个最常用的路径操作封装成 call 子程序：取父目录、取扩展名、取文件名、去扩展名、多段拼接、绝对化、相对化、规范化、取目录基名。可以整段复制到自己的脚本里当函数库用。', ST_BODY),
        Paragraph('路径相等判断的坑：Windows 路径不区分大小写，所以不能直接 if "!a!"=="!b!" 比较。正确做法是 if /i "!np1!"=="!np2!" 或者先 %%~fP 规范化再比较。UNC 路径的修饰符行为不一样——%%~dpUNC 会把 \\\\server\\share 拆到根级别。', ST_BODY),
        Paragraph('长路径（>260 字符）在现代 Windows 上需要注册表开启 HKLM\\SYSTEM\\CurrentControlSet\\Control\\FileSystem\\LongPathsEnabled=1，或者用 \\?\\ 前缀绕过。BAT 的 for %%P 在长路径下可能有问题，复杂情况交给 PowerShell。', ST_BODY),
        Paragraph('下一章进入进程管理和注册表。tasklist/taskkill、wmic process、注册表 HKLM/HKCU/HKCR/HKU/HKCC 五大根键的结构和操作，准备好了吗？', ST_BODY),
