        ['HKCR', 'HKEY_CLASSES_ROOT', 'HKEY_CLASSES_ROOT', '全局（合并 HKLM+HKCU）', '文件关联 COM 类注册', '间接', 'HKCU 覆盖 HKLM'],
        ['HKLM', 'HKEY_LOCAL_MACHINE', 'HKEY_LOCAL_MACHINE', '整机所有用户', '系统设置 软件安装', '需管理员', '被 HKCU 覆盖'],
        ['HKCU', 'HKEY_CURRENT_USER', 'HKEY_CURRENT_USER', '当前登录用户', '用户偏好 快捷方式', '当前用户', '最高覆盖优先级'],
