        Paragraph('注册表五大根键（HKCR HKLM HKCU HKU HKCC）必须理清作用域。HKCU 覆盖 HKLM，HKCR 是合并视图，HKCC 动态生成。安全上最要盯的是 HKLM\\Run、HKCU\\Run、Startup 文件夹这三个启动点——恶意软件最爱修改。', ST_BODY),
        Paragraph('进程监控脚本展示了 bat 里如何检查关键进程是否存在、扫描可疑进程名、审计所有启动位置。这三个功能组合起来就是一个轻量级的安全检查工具。tasklist 不支持通配符模糊搜索，用 findstr 配合。', ST_BODY),
        Paragraph('注册表操作的常用命令：reg query 查值、reg add 写值、reg delete 删值、reg export/import 导入导出。所有 reg 命令都支持 /v 指定值名、/t 指定类型、/d 指定数据。写 HKLM 下的键必须管理员权限。', ST_BODY),
