    # ============ 第10章 追加：网络命令汇总表 + net 命令子命令表 ============
    code10_extra_d = _build_code([
        '@echo off',
        'setlocal enabledelayedexpansion',
        'echo =============================================',
        'echo   第10章综合实战：网络诊断全家桶',
        'echo =============================================',
        'echo.',
        'echo === 1. 快速网络自检 ===',
        'echo --- 基本连通性 ---',
        'ping -n 1 127.0.0.1 >nul 2>&1 && echo [OK] 回环正常 || echo [FAIL] 回环异常',
        'ping -n 1 8.8.8.8 >nul 2>&1 && echo [OK] 外网可达 || echo [FAIL] 外网不可达',
        'ping -n 1 www.baidu.com >nul 2>&1 && echo [OK] DNS 正常 || echo [FAIL] DNS 异常',
        'echo.',
        'echo --- DNS 解析详细 ---',
        'nslookup www.baidu.com 2>nul | findstr /i "Address Name"',
        'echo.',
        'echo === 2. 详细网络信息 ===',
        'echo --- IP 配置 ---',
        'ipconfig /all | findstr /i "IP 网关 DNS MAC DHCP"',
        'echo.',
        'echo --- 路由表 ---',
        'route print 2>nul | findstr "0.0.0.0"',
        'echo.',
        'echo --- 端口监听 ---',
        'netstat -ano | findstr LISTENING | head -15',
        'echo.',
        'echo --- 活动连接 ---',
        'netstat -ano | findstr ESTABLISHED | head -10',
        'echo.',
        'echo === 3. net 命令快速参考 ===',
        'echo --- 共享资源 ---',
        'net share 2>nul',
        'echo.',
        'echo --- 当前用户 ---',
        'net user %username% 2>nul | findstr "上次登录 账户激活"',
        'echo.',
        'echo --- 工作组 ---',
        'net view 2>nul | head -10',
        'echo.',
        'echo === 4. tracert 路由追踪 ===',
        'tracert -d -h 8 www.baidu.com 2>nul',
        'echo.',
        'pause',
    ])
    code10_extra_e = _build_code([
        '@echo off',
        'setlocal enabledelayedexpansion',
        'echo =============================================',
        'echo   第10章进阶：网络延迟监控脚本',
        'echo   定时 ping 记录 RTT，超过阈值报警',
        'echo =============================================',
        'echo.',
        'set "LOG=%~dp0latency.log"',
        'set /p "target=输入要监控的目标(如 8.8.8.8): "',
        'if "!target!"=="" set "target=8.8.8.8"',
        'set /p "threshold=延迟阈值(ms, 如 100): "',
        'if "!threshold!"=="" set "threshold=100"',
        'set /p "interval=检查间隔(秒, 如 10): "',
        'if "!interval!"=="" set "interval=10"',
        'echo.',
        'echo 目标: !target!',
        'echo 阈值: !threshold! ms',
        'echo 间隔: !interval! 秒',
        'echo 日志: !LOG!',
        'echo 按 Ctrl+C 停止',
        'echo.',
        ':loop',
        'for /f "tokens=5 delims==< " %%t in (\'ping -n 1 !target! ^| findstr /i "时间"\') do (',
        '    set "rtt=%%t"',
        '    set "rtt=!rtt:ms=!"',
        '    if "!rtt!"=="" set "rtt=超时"',
        ')',
        'for /f "tokens=5 delims== " %%t in (\'ping -n 1 !target! ^| findstr /i "Average"\') do set "rtt=%%t"',
        'set "ts=%date% %time%"',
        'echo [!ts!] !target! - RTT=!rtt! ms',
        'if "!rtt!" neq "超时" (',
        '    set "rtt_num=!rtt!"',
        '    if !rtt_num! gtr !threshold! (',
        '        echo   [WARN] 延迟超阈值 !threshold!ms',
        '        echo [!ts!] WARN: RTT !rtt! ms !threshold! >> "!LOG!"',
        '    )',
        ') else (',
        '    echo   [FAIL] 超时',
        '    echo [!ts!] FAIL: ping timeout >> "!LOG!"',
        ')',
        'timeout /t !interval! >nul',
        'goto loop',
    ])
    code10_proj = _build_code([
        '@echo off',
        'setlocal enabledelayedexpansion',
        'echo =============================================',
        'echo   第10章项目：网络扫描工具集',
        'echo   端口扫描 / 网段扫描 / 服务探测',
        'echo =============================================',
        'echo.',
        'echo [1] 端口扫描（常用端口）',
        'echo [2] 网段快速扫描（192.168.1.x）',
        'echo [3] HTTP 服务探测',
        'echo [4] 网络接口详细信息',
        'set /p "mode=选择模式 [1-4]: "',
        'echo.',
        'if "!mode!"=="1" goto port_scan',
        'if "!mode!"=="2" goto subnet_scan',
        'if "!mode!"=="3" goto http_probe',
        'if "!mode!"=="4" goto iface_info',
        'goto end',
        ':port_scan',
        'set /p "host=要扫描的主机: "',
        'set "ports=21 22 23 25 53 80 110 135 139 443 445 3389 8080"',
        'echo 正在扫描 !host! 常用端口...',
        'for %%p in (!ports!) do (',
        '    echo   | findstr "." nul > "%temp%\\port_%%p.txt" 2>&1',
        '    (echo ^| set /p=) | telnet !host! %%p 2>nul | findstr "."',
        '    if !errorlevel!==0 (',
        '        echo   [OPEN] %%p',
        '    ) else (',
        '        echo   [CLOSED] %%p',
        '    )',
        ')',
        'goto end',
        ':subnet_scan',
        'echo 正在扫描 192.168.1.1-254 ...',
        'set /a online=0',
        'for /L %%i in (1,1,254) do (',
        '    ping -n 1 -w 300 192.168.1.%%i >nul 2>&1',
        '    if !errorlevel!==0 (',
        '        echo   [ONLINE] 192.168.1.%%i',
        '        set /a online+=1',
        '    )',
        ')',
        'echo.',
        'echo 在线主机: !online! 台',
        'goto end',
        ':http_probe',
        'set /p "url=要探测的HTTP服务: "',
        'echo 正在请求 !url! ...',
        'powershell -NoProfile -Command "try { $r=Invoke-WebRequest -Uri \'!url!\' -TimeoutSec 5; Write-Host StatusCode: $r.StatusCode; Write-Host ContentLength: $r.Content.Length } catch { Write-Host Error: $_.Exception.Message }"',
        'goto end',
        ':iface_info',
        'echo --- 所有网络接口 ---',
        'netsh interface show interface',
        'echo.',
        'echo --- 每个接口详细 ---',
        'ipconfig /all',
        'echo.',
        'echo --- 已连接的共享 ---',
        'net use 2>nul',
        'goto end',
        ':end',
        'pause',
    ])

