        Paragraph('net 命令有 19 个子命令，其中 net share/net use/net user/net start/net stop/net view 是日常最高频的。net use Z: \\\\server\\share /persistent:yes 映射驱动器；net start W32Time 启动时间服务；net user hacker /delete 删除账户。记住 net user /add 可以创建账户，配合 net localgroup Administrators hacker /add 提权到管理员。', ST_BODY),
