        Paragraph('端口扫描用 PowerShell Test-NetConnection 比 BAT 的 telnet 更可靠。telnet 在现代 Windows 上默认不启用，需要 OptionalFeatures 里打开。网段扫描用 ping -n 1 -w 300 + for /L 遍历 1-254，300ms 超时速度适中。', ST_BODY),
        Paragraph('netstat -ano 显示的 PID 可以用 tasklist /fi "pid eq N" 找到对应进程。这是 BAT 里定位"哪个进程占用了某个端口"的标准组合拳。', ST_BODY),
