    # ============ 第11章 追加：BAT与PowerShell互通10种姿势 + UAC提权三种方案 ============
    code11_extra_d = _build_code([
        '@echo off',
        'setlocal enabledelayedexpansion',
        'echo =============================================',
        'echo   第11章综合实战：BAT + PowerShell 互通',
        'echo   10 种从 BAT 调用/嵌入 PowerShell 的方式',
        'echo =============================================',
        'echo.',
        'echo === 方式 1: powershell -Command 直接内联 ===',
        'echo --- 获取当前日期时间 ---',
        'for /f %%d in (\'powershell -NoProfile -Command "Get-Date -Format \'yyyy-MM-dd HH:mm:ss\'"\') do set "dt=%%d"',
        'echo   !dt!',
        'echo.',
        'echo === 方式 2: powershell -File 外部脚本 ===',
        'echo   powershell -NoProfile -File script.ps1',
        'echo.',
        'echo === 方式 3: 从 stdin 读 PowerShell 代码 ===',
        'echo --- 用 here-string 传多行 ---',
        'powershell -NoProfile -Command "& { $PSVersionTable.PSVersion; Get-Date }"',
        'echo.',
        'echo === 方式 4: BAT 捕获 PowerShell 输出 ===',
        'for /f "delims=" %%l in (\'powershell -NoProfile -Command "Get-Process cmd | Select -First 1 Name,Id"\') do (',
        '    echo   %%l',
        ')',
        'echo.',
        'echo === 方式 5: PowerShell 捕获 BAT 退出码 ===',
        'powershell -NoProfile -Command "cmd /c \"dir C:\\Windows\\System32\\cmd.exe\" \"`$LASTEXITCODE\""',
        'echo.',
        'echo === 方式 6: BAT 设置变量让 PowerShell 读 ===',
        'set "bat_var=hello_from_bat"',
        'powershell -NoProfile -Command "Write-Host \'BAT says:\' $env:bat_var"',
        'echo.',
        'echo === 方式 7: PowerShell 写回给 BAT ===',
        'for /f "delims=" %%v in (\'powershell -NoProfile -Command "\'hello_from_powershell\'"\') do (',
        '    set "ps_var=%%v"',
        ')',
        'echo   BAT 收到: !ps_var!',
        'echo.',
        'echo === 方式 8: PowerShell Invoke-Command 远程 ===',
        'echo   powershell -Command "Invoke-Command -ComputerName server01 -ScriptBlock { Get-Process }"',
        'echo.',
        'echo === 方式 9: cmd /c 从 PowerShell 调 BAT ===',
        'echo   cmd /c "my_script.bat arg1"',
        'echo.',
        'echo === 方式 10: 混合脚本 (.bat + .ps1 结合) ===',
        'echo   BAT 用 for /f 包 PowerShell 输出，最经典模式',
        'echo.',
        'echo === Bonus: UAC 提权 ===',
        'echo --- 方案 A: runas (旧) ---',
        'echo   runas /user:admin "cmd /c my.bat"',
        'echo --- 方案 B: PowerShell Start-Process -Verb RunAs ---',
        'echo   powershell -Command "Start-Process cmd -ArgumentList \'/c my.bat\' -Verb RunAs"',
        'echo --- 方案 C: 自提权（最常用）---',
        'call :elevate',
        'pause',
        'exit /b 0',
        ':elevate',
        'net session >nul 2>&1',
        'if !errorlevel!==0 exit /b 0',
        'echo 需要管理员权限，正在请求 UAC...',
        'powershell -NoProfile -Command "Start-Process -FilePath \'cmd.exe\' -ArgumentList \'/c ""%~f0""\' -Verb RunAs"',
        'exit /b 0',
    ])
    code11_extra_e = _build_code([
        '@echo off',
        'setlocal enabledelayedexpansion',
        'echo =============================================',
        'echo   第11章进阶：完整自提权模板',
        'echo   检测管理员状态 -> UAC 弹窗 -> 重新启动',
        'echo =============================================',
        'echo.',
        'echo --- 检查当前权限 ---',
        'net session >nul 2>&1',
        'if !errorlevel!==0 (',
        '    echo [OK] 已经是管理员',
        '    goto run_as_admin',
        ')',
        'echo [INFO] 当前不是管理员，请求 UAC ...',
        'echo.',
        'rem === 方案 1: PowerShell Start-Process（最兼容）===',
        'powershell -NoProfile -Command ^',
        '  "Start-Process -FilePath `"cmd.exe`" ^',
        '   -ArgumentList `"/k ""%~f0"" %*`" ^',
        '   -Verb RunAs ^',
        '   -WorkingDirectory `"%~dp0""',
        'exit /b 0',
        ':run_as_admin',
        'echo --- 提权成功，执行管理员操作 ---',
        'echo.',
        'echo [1] 注册环境变量（机器级）',
        'setx /M MY_VAR "admin_value"',
        'echo.',
        'echo [2] 启动禁用的服务',
        'net start wuauserv',
        'echo.',
        'echo [3] 安装驱动/软件',
        'echo   （示例：静默安装）',
        'echo   msiexec /i package.msi /qn',
        'echo.',
        'echo [4] 修改系统设置',
        'reg add "HKLM\\SYSTEM\\CurrentControlSet\\Control\\FileSystem" /v LongPathsEnabled /t REG_DWORD /d 1 /f',
        'echo   已开启长路径支持',
        'echo.',
        'echo [5] 防火墙放行',
        'netsh advfirewall firewall add rule name="MyApp" dir=in action=allow protocol=TCP localport=8080',
        'echo   防火墙规则已添加',
        'echo.',
        'echo [完成] 所有管理员操作执行完毕',
        'echo 脚本将自动退出',
        'timeout /t 3 >nul',
        'exit /b 0',
    ])
    code11_proj = _build_code([
        '@echo off',
        'setlocal enabledelayedexpansion',
        'chcp 65001 >nul 2>&1',
        'echo =============================================',
        'echo   第11章项目：BAT 辅助 PowerShell 命令库',
        'echo   把常用 PowerShell 功能封装成 BAT call 子程序',
        'echo =============================================',
        'echo.',
        'call :ps_get_cpu',
        'call :ps_get_ram',
        'call :ps_get_uptime',
        'call :ps_top_processes',
        'call :ps_disk_info',
        'call :ps_os_info',
        'echo.',
        'echo === 全部调用完成 ===',
        'pause',
        'exit /b 0',
        ':ps_get_cpu',
        'for /f %%c in (\'powershell -NoProfile -Command "(Get-CimInstance Win32_Processor).LoadPercentage"\') do echo   CPU 负载: %%c %%',
        'exit /b 0',
        ':ps_get_ram',
        'for /f "tokens=*" %%r in (\'powershell -NoProfile -Command "$c=Get-CimInstance Win32_OperatingSystem; $total=[math]::Round($c.TotalVisibleMemorySize/1MB,1); $free=[math]::Round($c.FreePhysicalMemory/1MB,1); Write-Output \'${total} GB / ${free} GB free\'"\') do echo   内存: %%r',
        'exit /b 0',
        ':ps_get_uptime',
        'for /f %%t in (\'powershell -NoProfile -Command "(Get-Date) - (Get-CimInstance Win32_OperatingSystem).LastBootUpTime | ForEach-Object { $_.Days.ToString() + \'天 \' + $_.Hours.ToString() + \'小时\' }"\') do echo   运行时间: %%t',
        'exit /b 0',
        ':ps_top_processes',
        'echo --- Top 5 进程（CPU）---',
        'powershell -NoProfile -Command "Get-Process | Sort CPU -Descending | Select -First 5 Name,CPU | Format-Table -AutoSize"',
        'exit /b 0',
        ':ps_disk_info',
        'echo --- 磁盘信息 ---',
        'powershell -NoProfile -Command "Get-CimInstance Win32_LogicalDisk -Filter DriveType=3 | Select DeviceID, @{N=\'SizeGB\';E={[math]::Round($_.Size/1GB,1)}}, @{N=\'FreeGB\';E={[math]::Round($_.FreeSpace/1GB,1)}} | Format-Table -AutoSize"',
        'exit /b 0',
        ':ps_os_info',
        'echo --- 系统信息 ---',
        'powershell -NoProfile -Command "$os=Get-CimInstance Win32_OperatingSystem; Write-Host \"OS: $($os.Caption)\"; Write-Host \"Version: $($os.Version)\"; Write-Host \"Arch: $($os.OSArchitecture)\"; Write-Host \"InstallDate: $($os.InstallDate)\""',
        'exit /b 0',
    ])

