        Paragraph('端口号表按安全风险从极高到低排序，永恒之蓝的 445、Redis 的 6379、MongoDB 的 27017、RDP 的 3389 都是"高危四件套"。生产环境务必关闭/限制来源 IP。临时调试放行时要用 netsh advfirewall firewall add rule ... dir=in action=allow。', ST_BODY),
        Paragraph('netsh wlan 是 BAT 操作无线的唯一官方方式。最酷的三个 trick：netsh wlan show profile name="SSID" key=clear 可以明文读 WiFi 密码、netsh wlan export profile folder=. key=clear 批量导出所有 WiFi 配置（含密码！）、netsh wlan set hostednetwork mode=allow ssid= key= 创建移动热点。', ST_BODY),
        Paragraph('端口 -> 进程的映射脚本演示了 BAT 里如何把 netstat 的输出解析成 PID 再用 tasklist 查进程名。关键是 netstat -ano 显示每个连接的 PID，然后 tasklist /fi "pid eq N" 查名字。BAT 里做这个比 GUI 还方便。', ST_BODY),
