    # ============ 第14章 追加：BAT 黑科技技巧清单 + 安全加固检查清单 ============
    code14_extra_d = _build_code([
        '@echo off',
        'setlocal enabledelayedexpansion',
        'chcp 65001 >nul 2>&1',
        'echo =============================================',
        'echo   第14章综合实战：BAT 黑科技技巧合集',
        'echo   15 个让你 BAT 水平 +1 的技巧',
        'echo =============================================',
        'echo.',
        'rem === 技巧 1: for %%A in (%%Z) === 遍历文件 ===',
        'echo [1/15] for %%A in (*.txt) 文件遍历（绕过空格）:',
        'for %%A in ("%windir%\\System32\\*.exe") do echo   %%~nxA | head -3',
        'echo.',
        'rem === 技巧 2: 变量延迟展开 "!" vs "%" ===',
        'echo [2/15] "%%" 预处理 vs "!" 延迟:',
        'set "n=5"',
        'for /L %%i in (1,1,!n!) do (',
        '    set /a counter+=1',
        '    echo   这是第 %%i 次循环（counter=!counter!）',
        ')',
        'echo.',
        'rem === 技巧 3: 数组模拟 ===',
        'echo [3/15] 数组模拟 (array[index]):',
        'set "arr[0]=Mon"',
        'set "arr[1]=Tue"',
        'set "arr[2]=Wed"',
        'set "arr[3]=Thu"',
        'set "arr[4]=Fri"',
        'set "arr[5]=Sat"',
        'set "arr[6]=Sun"',
        'for /L %%i in (0,1,6) do echo   arr[%%i]=!arr[%%i]!',
        'echo.',
        'rem === 技巧 4: 字符串替换 ===',
        'echo [4/15] 字符串替换:',
        'set "msg=Hello World BAT"',
        'echo   原文: !msg!',
        'echo   替换 BAT -^> CMD: !msg:BAT=CMD!',
        'echo   去掉空格: !msg: =!',
        'echo   去掉 Hello : !msg:Hello =!',
        'echo.',
        'rem === 技巧 5: 截取子串 ===',
        'echo [5/15] 截取子串 :~start,length:',
        'set "long=Hello World from BAT"',
        'echo   原文: !long!',
        'echo   :~0,5:   !long:~0,5!',
        'echo   :~-5:    !long:~-5!',
        'echo   :~6,5:   !long:~6,5!',
        'echo.',
        'rem === 技巧 6: 用 %random% 生成随机数 ===',
        'echo [6/15] 随机数生成:',
        'set /a r=%random% %% 100',
        'echo   %random% %% 100 = !r!',
        'echo.',
        'rem === 技巧 7: enableDelayedExpansion + !var! ===',
        'echo [7/15] 延迟展开在括号块里:',
        'set "name=before"',
        'if !name!==before (',
        '    set "name=after"',
        '    echo   name 立即变成 !name!',
        ')',
        'echo.',
        'rem === 技巧 8: 管道右边不继承变量 ===',
        'echo [8/15] 管道陷阱:',
        'set "var=test"',
        'echo test | findstr "." >nul',
        'echo   管道之后 var=!var!',
        'echo   （如果管道是多行，右边是子 shell）',
        'echo.',
        'rem === 技巧 9: & ^| ^> 特殊字符转义 ===',
        'echo [9/15] 转义特殊字符:',
        'echo   输出管道符: ^|',
        'echo   输出大于号: ^>',
        'echo   输出百分号: %%',
        'echo.',
        'rem === 技巧 10: goto :eof 退出 call ===',
        'echo [10/15] goto :eof 从 call 返回:',
        'call :test_goto_eof',
        'echo   call 返回后的代码正常执行',
        'echo.',
        'rem === 技巧 11: call :func 传参 ===',
        'echo [11/15] call 传参 + %%~1 去引号:',
        'call :demo "hello world" bat_cmd',
        'echo.',
        'rem === 技巧 12: enableExtensions ===',
        'echo [12/15] setlocal enableextensions 高级特性:',
        'echo   启用更多 %~ 修饰符等',
        'echo.',
        'rem === 技巧 13: !var:str=replacement! ===',
        'echo [13/15] 变量替换语法（全部替换）:',
        'set "path=C:\\Users\\Me\\docs"',
        'echo   把 \\ 替换为 /: !path:\\=/!',
        'echo.',
        'rem === 技巧 14: errorlevel 判断 ===',
        'echo [14/15] errorlevel 和 if 配合:',
        'ver >nul 2>&1',
        'echo   ver 的 errorlevel=!errorlevel!',
        'echo.',
        'rem === 技巧 15: 在 BAT 里嵌套 PowerShell ===',
        'echo [15/15] 一行 PowerShell:',
        'for /f %%d in (\'powershell -NoProfile -Command "Get-Date -Format \'yyyy-MM-dd\'"\') do echo   今天是 %%d',
        'echo.',
        'pause',
        'exit /b 0',
        ':test_goto_eof',
        'echo   在 call 中执行',
        'goto :eof',
        'echo   这行不会执行',
        ':demo',
        'echo   参数 1: [%~1]',
        'echo   参数 2: [%~2]',
        'exit /b 0',
    ])
    code14_extra_e = _build_code([
        '@echo off',
        'setlocal enabledelayedexpansion',
        'chcp 65001 >nul 2>&1',
        'echo =============================================',
        'echo   第14章进阶：BAT 混淆与隐藏技术',
        'echo   安全研究/对抗恶意脚本分析',
        'echo =============================================',
        'echo.',
        'rem 注意: 以下技术仅用于研究/教育目的',
        'rem 不要用来做恶意事情！',
        'rem =========================================',
        'echo === 1. 字符替换 ===',
        'echo 把 "echo" 中的字母拆到变量里:',
        'set "e=e" & set "c=c" & set "h=h" & set "o=o"',
        'set "hide_cmd=!e!!c!!h!!o!"',
        'call :call_hidden',
        'echo.',
        'echo === 2. 环境变量拼接 ===',
        'set "cmd_part=cm"',
        'set "cmd_part2=d.exe"',
        'set "full_cmd=!cmd_part!!cmd_part2!"',
        'echo 拼接出 !full_cmd!',
        'echo.',
        'echo === 3. certutil 下载（隐式）===',
        'echo   certutil -urlcache -split -f url file',
        'echo   certutil 也能做编码/解码',
        'echo.',
        'echo === 4. powershell -enc（Base64）===',
        'echo   powershell -Command "IEX ([Text.Encoding]::UNICODE.GetString([Convert]::FromBase64String(\'BASE64\')))"',
        'echo.',
        'echo === 5. mshta 执行 JScript ===',
        'echo   mshta javascript:alert(1)',
        'echo   mshta vbscript:msgbox(1)',
        'echo.',
        'echo === 6. rundll32 执行 DLL ===',
        'echo   rundll32 url.dll,FileProtocolHandler http://example.com',
        'echo.',
        'echo === 7. 双引号陷阱 ===',
        'echo   命令字符串中的引号嵌套处理',
        'echo.',
        'echo === 8. for /f 反向 shell ===',
        'echo   for /f ... in (\'cmd /c "..."\') do ...',
        'echo.',
        'echo === 9. 自复制到启动 ===',
        'echo   copy script.bat "%appdata%\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\"',
        'echo.',
        'echo === 10. reg add HKLM Run 启动项 ===',
        'echo   reg add HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Run /v "name" /t REG_SZ /d "path" /f',
        'echo.',
        'echo === 安全提示 ===',
        'echo 以上技术被 BAT 病毒大量使用',
        'echo 安全软件会监控这些行为',
        'echo 合法场景请用标准手段（schtasks + 签名脚本）',
        'echo.',
        'pause',
        'exit /b 0',
        ':call_hidden',
        '!hide_cmd! 执行了（变量展开）',
        'exit /b 0',
    ])
    code14_proj = _build_code([
        '@echo off',
        'setlocal enabledelayedexpansion',
        'chcp 65001 >nul 2>&1',
        'echo =============================================',
        'echo   第14章项目：Windows 安全加固审计',
        'echo   一键检查 20+ 安全项',
        'echo =============================================',
        'echo.',
        'set /a pass=0',
        'set /a fail=0',
        'set /a warn=0',
        'echo === 开始安全审计 ===',
        'echo 时间: %date% %time%',
        'echo.',
        'rem === 1. 防火墙 ===',
        'echo [1/20] Windows 防火墙状态:',
        'netsh advfirewall show allprofiles state | findstr "开 ON" >nul 2>&1',
        'if !errorlevel!==0 (echo   [OK] 已开启 & set /a pass+=1) else (echo   [FAIL] 已关闭 & set /a fail+=1)',
        'echo.',
        'rem === 2. 自动更新 ===',
        'echo [2/20] Windows Update 状态:',
        'sc query wuauserv 2>nul | findstr "RUNNING" >nul 2>&1',
        'if !errorlevel!==0 (echo   [OK] 运行中 & set /a pass+=1) else (echo   [WARN] 服务未运行 & set /a warn+=1)',
        'echo.',
        'rem === 3. 防病毒 ===',
        'echo [3/20] 防病毒软件:',
        'powershell -NoProfile -Command "Get-MpComputerStatus" 2>nul | findstr /i "RealTimeProtectionEnabled" >nul 2>&1',
        'if !errorlevel!==0 (echo   [OK] Windows Defender 启用 & set /a pass+=1) else (echo   [WARN] 未检测到 AV & set /a warn+=1)',
        'echo.',
        'rem === 4. Guest 账户 ===',
        'echo [4/20] Guest 账户:',
        'net user guest 2>nul | findstr "账户激活 否" >nul 2>&1',
        'if !errorlevel!==0 (echo   [OK] 已禁用 & set /a pass+=1) else (echo   [WARN] 可能启用 & set /a warn+=1)',
        'echo.',
        'rem === 5. 密码策略 ===',
        'echo [5/20] 最小密码长度:',
        'net accounts 2>nul | findstr /i "最短密码长度"',
        'echo.',
        'rem === 6. SMB v1 ===',
        'echo [6/20] SMB v1 协议:',
        'sc query lanmanworkstation 2>nul | findstr "SMB1" >nul 2>&1',
        'echo   （建议禁用 SMB v1）',
        'echo.',
        'rem === 7. 远程桌面 ===',
        'echo [7/20] RDP (3389) 状态:',
        'netstat -ano | findstr ":3389" | findstr LISTENING',
        'if !errorlevel!==0 (echo   [WARN] RDP 正在监听 & set /a warn+=1) else (echo   [OK] 未监听 & set /a pass+=1)',
        'echo.',
        'rem === 8. 共享文件夹 ===',
        'echo [8/20] 共享文件夹:',
        'net share 2>nul',
        'echo.',
        'rem === 9. 启动项审计 ===',
        'echo [9/20] 启动项数量:',
        'set /a runcount=0',
        'for /f "delims=" %%v in (\'reg query "HKLM\\Software\\Microsoft\\Windows\\CurrentVersion\\Run" 2^>nul ^| find /c /v "HKEY_"\') do set /a runcount+=%%v',
        'echo   HKLM\\Run 有 !runcount! 个项',
        'if !runcount! gtr 5 (echo   [WARN] 启动项过多 & set /a warn+=1) else (echo   [OK] 正常 & set /a pass+=1)',
        'echo.',
        'rem === 10. 管理员账户检查 ===',
        'echo [10/20] Administrator 账户状态:',
        'net user administrator 2>nul | findstr "账户激活"',
        'echo.',
        'rem === 11. 补丁状态 ===',
        'echo [11/20] 最近更新:',
        'wmic qfe get installdate 2>nul | sort -r | head -5',
        'echo.',
        'rem === 12. 磁盘加密 ===',
        'echo [12/20] BitLocker 状态:',
        'manage-bde -status C: 2>nul | findstr "转换状态"',
        'echo.',
        'rem === 13. 用户账户控制 ===',
        'echo [13/20] UAC 设置:',
        'reg query HKLM\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System /v EnableLUA 2>nul | findstr "0x1" >nul 2>&1',
        'if !errorlevel!==0 (echo   [OK] UAC 已启用 & set /a pass+=1) else (echo   [FAIL] UAC 已禁用 & set /a fail+=1)',
        'echo.',
        'rem === 14. 密码过期策略 ===',
        'echo [14/20] 密码过期策略:',
        'net accounts 2>nul | findstr "强制用户在 x 天后更改密码"',
        'echo.',
        'rem === 15. 端口暴露 ===',
        'echo [15/20] 高风险端口暴露:',
        'for %%p in (23 445 3389 5985) do (',
        '    netstat -ano | findstr ":%%p " | findstr LISTENING >nul 2>&1',
        '    if !errorlevel!==0 (echo   [WARN] 端口 %%p 正在监听)',
        ')',
        'echo.',
        'rem === 16. 服务运行状态 ===',
        'echo [16/20] 关键服务:',
        'for %%s in (wuauserv wscsearch bits) do (',
        '    sc query %%s 2>nul | findstr "RUNNING" >nul 2>&1',
        '    if !errorlevel!==0 (echo   %%s - OK) else (echo   %%s - NOT RUNNING)',
        ')',
        'echo.',
        'rem === 17. 自动运行软件 ===',
        'echo [17/20] 已安装软件数量:',
        'wmic product get name 2>nul | find /c /v "Name"',
        'echo.',
        'rem === 18. PATH 环境变量 ===',
        'echo [18/20] PATH 检查（当前目录风险）:',
        'echo %PATH% | findstr /c:";.;" >nul 2>&1 && echo [FAIL] 路径中包含当前目录 || echo [OK] 无风险',
        'echo.',
        'rem === 19. 最近安装程序 ===',
        'echo [19/20] 最近安装的程序:',
        'wmic product get name,installdate 2>nul | sort /+50 | tail -10',
        'echo.',
        'rem === 20. 审计日志 ===',
        'echo [20/20] 安全日志大小:',
        'wevtutil gl Security 2>nul | findstr "size"',
        'echo.',
        'echo ==========================================',
        'echo  安全审计完成',
        'echo  通过: !pass!  警告: !warn!  失败: !fail!',
        'echo  总项: !pass!+!warn!+!fail!',
        'echo ==========================================',
        'pause',
    ])

    tbl14a_data = [
        ['技巧编号', '技巧名称', '核心语法', '说明'],
        ['1', '变量延迟展开', 'setlocal enabledelayedexpansion', '括号块内动态变量'],
        ['2', '数组模拟', 'set "arr[i]=value"', 'BAT 没有数组，用变量名模拟'],
        ['3', '字符串替换', '!var:old=new!', '全部替换，无局部替换'],
        ['4', '截取子串', '!var:start,len!', '支持负数从末尾起'],
        ['5', '随机数', '%random% %% N', '0-32767，取模后指定范围'],
        ['6', 'for %%P in (...) do', '%%~dpP %%~nxP', '路径修饰符在 for 中同样可用'],
        ['7', 'call :func arg1 arg2', '%~1 %~2 接收参数', '%%~ 自动去引号'],
        ['8', 'exit /b 退出子程序', 'exit /b N', '设 errorlevel 为 N'],
        ['9', 'goto :eof 返回 call', 'goto :eof', '从 call 调用的 label 返回'],
        ['10', '& ^| ^> 特殊转义', 'echo a^|b', '| > < & 在 echo 中要转义'],
        ['11', '批处理参数 %0-%9', '%%0 到 %%9 + %%*', '0=自身路径'],
        ['12', 'set /a 算术运算', 'set /a x+=1', '支持 + - * / %'],
        ['13', 'if errorlevel N', 'if !errorlevel!==0', '>=N 为真，精确等于要用延迟'],
        ['14', '&& 成功 || 失败', 'cmd1 && cmd2 || cmd3', '链式错误处理'],
        ['15', 'call :func & exit /b', 'call :sub 后直接 exit', '防止 fall-through'],
        ['16', 'pushd/popd', 'pushd "path"', 'pushd UNC 路径自动映射'],
        ['17', 'start 新进程', 'start "" cmd /c "..."', '第一个引号是窗口标题占位'],
        ['18', 'title / color / prompt', 'title MyBat & color 0A', '美化 cmd 窗口'],
        ['19', 'chcp 切换代码页', 'chcp 65001 UTF-8', '中文乱码关键'],
        ['20', 'for /f 捕获输出', 'for /f %%v in (\'cmd\')', 'BAT 捕获命令输出唯一方式'],
    ]
    t14a = Table(_wrap_table_rows(tbl14a_data), colWidths=[21.9*mm, 35.1*mm, 52.7*mm, 48.3*mm])
