        ['RDP 暴露', 'netstat -ano findstr 3389', '无 LISTENING', '远程控制入侵', '防火墙限制来源 IP'],
        ['共享文件夹', 'net share', '非必要不共享', '数据泄露', 'net share /delete name'],
        ['启动项审计', 'reg query HKLM\\...Run', '最少项目', '恶意软件持久化', '手动审查/删除不需要'],
        ['补丁安装', 'wmic qfe get', '最近安装', '已知漏洞', 'Windows Update'],
        ['BitLocker', 'manage-bde -status', '转换状态=完全加密', '丢数据/盗数据', '启用 BitLocker'],
        ['UAC', 'EnableLUA=1', '已启用', '无弹窗静默执行', '保持默认'],
