        ['屏保密码', 'HKCU\\Control Panel\\Desktop', 'ScreenSaverIsSecure=1', '无人值守入侵', '组策略强制'],
        ['自动登录', 'Winlogon AutoAdminLogon=0', '已禁用', '绕过密码', '设置为 0'],
        ['执行策略', 'Get-ExecutionPolicy', 'Restricted', '执行恶意脚本', 'Set-ExecutionPolicy -Scope CurrentUser RemoteSigned'],
        ['WinRM', 'Get-Service WinRM', 'Stopped', '远程管理端口暴露', 'Disable-PSRemoting'],
