        Paragraph('BAT 的 20 个"黑科技"技巧本质上都是 cmd 语言的角落特性：延迟展开（括号块内动态更新）、数组模拟（变量名里带下标）、字符串替换（!var:a=b!）、截取子串（!var:~0,5!）、%random% 随机数。这些东西在任何 BAT 脚本里都会反复出现。', ST_BODY),
        Paragraph('BAT 混淆/隐藏技术（certutil 下载、powershell -enc、mshta、rundll32、双引号陷阱、Base64 编码）是安全研究和对抗恶意软件分析的必修课。但合法的自动化脚本不要用这些——签名脚本 + 明确的计划任务 + 清晰的代码才是正道。', ST_BODY),
        Paragraph('安全加固审计脚本把 20 个关键安全项的命令 + 期望结果 + 修复命令串起来。实际环境定期跑一遍就能发现问题。记住：永恒之蓝的 445 端口、RDP 的 3389、Redis 的 6379、MongoDB 的 27017 这四个高危端口是勒索软件最爱攻击的。', ST_BODY),
        Paragraph('smb v1 协议在 Windows 10 1709+ 已默认禁用，但旧系统可能还开着。Set-SmbServerConfiguration -EnableSMB1Protocol $false 一键关闭。关闭 SMB v1 后无法与非常老的设备互通，谨慎操作。', ST_BODY),
        Paragraph('BitLocker 加密（manage-bde -on C:）、UAC 不要关闭、管理员账户改名、Guest 账户禁用这些是"基础四件套"，每台 Windows 机器都应该做。', ST_BODY),
        Paragraph('至此全书 14 章 + 两次扩充全部完成。BAT 脚本的学习没有终点——cmd.exe 里还有很多未发现的角落等待探索。', ST_BODY),
