    t1big.setStyle(TableStyle([
        ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#1A5276')),
        ('GRID', (0, 0), (-1, -1), 0.4, colors.HexColor('#D5D8DC')),
        ('ROWBACKGROUNDS', (0, 1), (-1, -1), [colors.white, colors.HexColor('#F4F6F6')]),
        ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
        ('TOPPADDING', (0, 0), (-1, -1), 2),
        ('BOTTOMPADDING', (0, 0), (-1, -1), 2),
        ('LEFTPADDING',   (0, 0), (-1, -1), 6),
        ('RIGHTPADDING',  (0, 0), (-1, -1), 6),
    ]))

    ex[1] = ex[1] + [
        Spacer(1, 20),
        Paragraph('进阶项目1：完整的系统环境诊断脚本', ST_SEC_TITLE),
        Paragraph('这个 100 行的 BAT 脚本涵盖了系统诊断的 7 大维度：OS 版本、补丁列表、启动时间、CPU 参数、内存详情、磁盘信息、网络适配器。脚本不仅把结果打印到控制台，还自动保存为 diagnose_report_YYYYMMDD.txt。这种"控制台 + 文件"双输出模式是运维脚本的标准做法。', ST_BODY),
        make_code_block(code1_diag),
        Spacer(1, 15),
        Paragraph('系统诊断指标汇总表（25 项）', ST_SEC_TITLE),
        t1big,
        Spacer(1, 15),
        Paragraph('写系统诊断脚本时最重要的三个点：第一是容错——wmic 在某些精简版 Windows 上可能失败，要把错误抑制掉（2>nul）；第二是输出格式统一，上面用了 /format:list 和 /format:table 两种，list 适合脚本解析，table 适合人看；第三是延迟扩展，像本脚本里计算内存 GB 数就需要 !var! 而不是 %var%。', ST_BODY),
        Paragraph('Windows 的系统信息通过四种渠道获取：环境变量（%COMPUTERNAME%、%NUMBER_OF_PROCESSORS%）、wmic WMI 查询、ipconfig/getmac 工具、注册表。环境变量最快但信息少，wmic 最全但稍慢，注册表最底层但最灵活。大型诊断脚本通常组合使用。', ST_BODY),
        Paragraph('输出到文件时建议用引号包裹路径以防空格，同时在括号块内用 >> 追加重定向比单行 echo 重定向效率高。生成的报告可以定期对比——比如每周跑一次，观察磁盘空间是否持续下降、补丁是否及时安装、CPU 温度是否异常。这些趋势信息比单次检查更有价值。', ST_BODY),
        Paragraph('严重程度列（高/中/低）是给运维看的快速 triage 信号："高"意味着可能有安全漏洞或系统即将出问题，需要立即处理；"中"意味着性能或兼容性有风险；"低"是提示性质。写任何监控脚本时，这种分级输出都比纯文字描述有用得多。', ST_BODY),
    ]

    # ============ ex[2] 第三波：交互式安装向导模板 ============
    code2_install = _build_code([
        '@echo off',
        'setlocal enabledelayedexpansion',
        'title 交互式安装向导 v2.0',
        'color 0E',
        '',
        'rem ============================================================',
        'rem  交互式安装向导模板',
        'rem  用 set /p + choice 实现 yes/no 安装流程',
        'rem  带进度显示、错误处理、回滚支持',
        'rem ============================================================',
        '',
        'set "APP_NAME=我的 BAT 工具包"',
        'set "APP_VERSION=1.2.0"',
        'set "INSTALL_DIR=C:\\Program Files\\MyBATTool"',
        'set "BACKUP_DIR=%~dp0backup_%random%"',
        'set "LOG_FILE=%~dp0install_log.txt"',
        'set /a step=0',
        '',
        'echo. > "%LOG_FILE%"',
        'echo [%date% %time%] ============= 安装开始 ============= >> "%LOG_FILE%"',
        '',
        ':WELCOME',
        'cls',
        'echo.',
        'echo    ================================================',
        'echo.         欢迎使用 !APP_NAME! v!APP_VERSION!',
        'echo    ================================================',
        'echo.',
        'echo    本向导将引导您完成安装过程。',
        'echo    安装前请关闭其他正在运行的程序。',
        'echo.',
        'echo.         [1] 开始安装',
        'echo.         [2] 查看许可协议',
        'echo.         [3] 退出安装',
        'echo.',
        'set /p "wel=请选择: "',
        'if "!wel!"=="1" goto :LICENSE',
        'if "!wel!"=="2" goto :SHOW_LICENSE',
        'if "!wel!"=="3" goto :CANCEL',
        'goto :WELCOME',
        '',
        ':SHOW_LICENSE',
        'cls',
        'echo.',
        'echo === !APP_NAME! 许可协议 ===',
        'echo 本软件按 MIT 许可发布。',
        'echo 你可以自由使用、修改、分发。',
        'echo 作者不承担使用本软件造成的任何损失。',
        'echo.',
        'echo 按任意键返回...',
        'pause >nul',
        'goto :WELCOME',
        '',
        ':LICENSE',
        'cls',
        'echo.',
        'echo 是否接受以上许可协议？',
        'choice /C YN /M "接受并继续安装(Y) 或 取消(N)"',
        'if errorlevel 2 goto :CANCEL',
        'if errorlevel 1 goto :CHOOSE_DIR',
        '',
        ':CHOOSE_DIR',
        'cls',
        'echo.',
        'echo.         默认安装目录: !INSTALL_DIR!',
        'echo.',
        'choice /C YNC /M "使用默认目录(Y) 自定义(C) 取消(N)"',
        'if errorlevel 3 goto :CANCEL',
        'if errorlevel 2 (',
        '    echo.',
        '    set /p "INSTALL_DIR=请输入安装目录: "',
        '    if "!INSTALL_DIR!"=="" (set "INSTALL_DIR=C:\\Program Files\\MyBATTool")',
        ')',
        'echo 选择的目录: !INSTALL_DIR! >> "%LOG_FILE%"',
        '',
        'rem 权限检查',
        'if not exist "!INSTALL_DIR!" (',
        '    echo 正在创建安装目录...',
        '    mkdir "!INSTALL_DIR!" 2>nul',
        '    if errorlevel 1 (',
        '        echo.',
        '        echo [错误] 无法创建目录 !INSTALL_DIR!',
        '        echo        请以管理员身份运行本脚本。',
        '        choice /C AR /M "管理员权限运行(A) 返回修改目录(R)"',
        '        if errorlevel 2 goto :CHOOSE_DIR',
        '        powershell -Command "Start-Process cmd -ArgumentList \'/c %~f0\' -Verb RunAs"',
        '        exit /b',
        '    )',
        ')',
        '',
        'rem 备份已安装版本',
        'if exist "!INSTALL_DIR!\\*" (',
        '    echo 检测到已有版本，正在备份...',
        '    mkdir "!BACKUP_DIR!" 2>nul',
        '    xcopy /E /Y /Q "!INSTALL_DIR!" "!BACKUP_DIR!\\" >nul 2>&1',
        '    echo 已备份到 !BACKUP_DIR! >> "%LOG_FILE%"',
        '    echo 备份完成。',
        ')',
        '',
        'goto :CONFIRM',
        '',
        ':CONFIRM',
        'cls',
        'echo.',
        'echo    === 安装摘要 ===',
        'echo    应用名称:  !APP_NAME! v!APP_VERSION!',
        'echo    安装目录:  !INSTALL_DIR!',
        'echo    目标用户:  %USERNAME%',
        'echo    计算机:    %COMPUTERNAME%',
        'echo.',
        'choice /C YN /M "确认开始安装"',
        'if errorlevel 2 goto :CHOOSE_DIR',
        'if errorlevel 1 goto :DO_INSTALL',
        '',
        ':DO_INSTALL',
        'cls',
        'echo.',
        'echo    正在安装 !APP_NAME! v!APP_VERSION!',
        'echo.',
        '',
        'set /a total_steps=5',
        'rem Step 1: 清理旧文件',
        'set /a step+=1',
        'echo [!step!/!total_steps!] 清理旧文件...',
        'if exist "!INSTALL_DIR!\\*.bak" del /q "!INSTALL_DIR!\\*.bak" 2>nul',
        'call :ShowProgress !step! !total_steps!',
        '',
        'rem Step 2: 复制主文件',
        'set /a step+=1',
        'echo [!step!/!total_steps!] 复制主程序文件...',
        'mkdir "!INSTALL_DIR!\\bin" 2>nul',
        'mkdir "!INSTALL_DIR!\\modules" 2>nul',
        'mkdir "!INSTALL_DIR!\\docs" 2>nul',
        'copy /y "%~dp0main.bat" "!INSTALL_DIR!\\bin\\" >nul 2>&1',
        'copy /y "%~dp0modules\\*.bat" "!INSTALL_DIR!\\modules\\" >nul 2>&1',
        'copy /y "%~dp0README.txt" "!INSTALL_DIR!\\docs\\" >nul 2>&1',
        'echo  文件复制完成 >> "%LOG_FILE%"',
        'call :ShowProgress !step! !total_steps!',
        '',
        'rem Step 3: 创建快捷方式',
        'set /a step+=1',
        'echo [!step!/!total_steps!] 创建开始菜单快捷方式...',
        'set "START_MENU=%APPDATA%\\Microsoft\\Windows\\Start Menu\\Programs\\MyBATTool"',
        'mkdir "!START_MENU!" 2>nul',
        'powershell -Command "$s=New-Object -ComObject WScript.Shell; $c=$s.CreateShortcut(\'!START_MENU!\\MyBATTool.lnk\'); $c.TargetPath=\'!INSTALL_DIR!\\bin\\main.bat\'; $c.WorkingDirectory=\'!INSTALL_DIR!\'; $c.Save()"',
        'call :ShowProgress !step! !total_steps!',
        '',
        'rem Step 4: 注册表写入',
        'set /a step+=1',
        'echo [!step!/!total_steps!] 注册到系统...',
        'reg add "HKCU\\Software\\MyBATTool" /v InstallDir /t REG_SZ /d "!INSTALL_DIR!" /f >nul',
        'reg add "HKCU\\Software\\MyBATTool" /v Version /t REG_SZ /d "!APP_VERSION!" /f >nul',
        'reg add "HKCU\\Software\\MyBATTool" /v InstallDate /t REG_SZ /d "%date%" /f >nul',
        'call :ShowProgress !step! !total_steps!',
        '',
        'rem Step 5: PATH 更新',
        'set /a step+=1',
        'echo [!step!/!total_steps!] 添加到 PATH...',
        'call :AddToPath "!INSTALL_DIR!\\bin"',
        'call :ShowProgress !step! !total_steps!',
        '',
        'echo.',
        'echo 安装完成！',
        'echo.',
        'choice /C YN /M "是否立即启动 !APP_NAME!"',
        'if errorlevel 1 start "" "!INSTALL_DIR!\\bin\\main.bat"',
        'goto :FINISH',
        '',
        ':CANCEL',
        'echo.',
        'echo 安装已取消。已备份文件保存在 !BACKUP_DIR!',
        'echo 如需清理备份，手动删除该文件夹即可。',
        'echo [%date% %time%] 安装已取消 >> "%LOG_FILE%"',
        'pause',
        'exit /b',
        '',
        ':FINISH',
        'echo [%date% %time%] 安装完成 >> "%LOG_FILE%"',
        'echo.',
        'echo 感谢使用 !APP_NAME!！',
        'echo 安装目录: !INSTALL_DIR!',
        'echo 日志文件: !LOG_FILE!',
        'pause',
        'exit /b',
        '',
        ':ShowProgress',
        'set /a cur=%1*30/%2',
        'set /a max=30',
        'set "bar="',
        'for /L %%i in (1,1,!cur!) do set "bar=!bar!█"',
        'set /a empty=!max!-!cur!',
        'for /L %%i in (1,1,!empty!) do set "bar=!bar!░"',
        '<nul set /p "=  [!bar!] %1/%2\r"',
        'ping -n 2 127.0.0.1 >nul',
        'exit /b',
        '',
        ':AddToPath',
        'set "new=%~1"',
        'set "cur_path="',
        'for /f "tokens=2 delims==" %%p in (\'reg query HKCU\\Environment /v PATH 2^>nul ^| findstr PATH\') do set "cur_path=%%p"',
        'echo !cur_path! | findstr /i "!new!" >nul',
        'if errorlevel 1 (',
        '    reg add "HKCU\\Environment" /v PATH /t REG_EXPAND_SZ /d "!cur_path!;!new!" /f >nul 2>&1',
        '    echo  已添加到用户 PATH >> "%LOG_FILE%"',
        ')',
        'exit /b',
    ])
    tbl2_data = [
        ['安装阶段', '典型任务', 'BAT 实现方式', '错误处理', '回滚策略', '时间估算', '关键注意'],
        ['欢迎页', '显示 Logo + 版本', 'cls + echo 多边框', 'choice 输入校验', '退出不写文件', '<1秒', '不要用 ASCII art 过大'],
        ['许可协议', '显示 MIT/GPL 文本', 'type license.txt | more', '用户必须 accept', '拒绝=直接退出', '<1秒', 'choice /C YN 最可靠'],
        ['目录选择', '默认 vs 自定义', 'set /p + 权限检查', 'mkdir 失败提 UAC', '回退到上次路径', '2秒', '路径含空格必须双引号'],
        ['权限检查', '管理员验证', 'net session >nul 2>nul', '非管理员弹 UAC', '等待用户重试', '3秒', 'HKLM 操作必须 admin'],
        ['备份旧版', 'xcopy /E /Y 备份', 'xcopy 或 robocopy', '磁盘不足警告', '跳过备份继续', '5-10秒', '备份目录用 %random% 唯一'],
        ['文件复制', '主程序+库文件', 'xcopy /E /Y /Q', 'copy 失败重试3次', '恢复备份', '10-30秒', 'robocopy 更稳（可重试）'],
        ['快捷方式', '开始菜单入口', 'WScript.Shell COM', 'COM 调用失败', '跳过（非关键）', '2秒', 'PowerShell 调用更可靠'],
        ['注册表写入', '安装信息持久化', 'reg add /v /t /d /f', 'reg add 访问拒绝', '跳过（非关键）', '1秒', 'HKCU 比 HKLM 权限松'],
        ['PATH 更新', '加入命令搜索路径', 'reg query + 拼接', 'PATH 过长警告', '放弃添加', '1秒', '用 reg query 读当前值'],
        ['DLL 注册', 'COM 组件注册', 'regsvr32 /s', 'regsvr32 失败', '跳过', '3秒', '64位系统区分 syswow64'],
        ['服务注册', '后台服务安装', 'sc create + sc config', 'sc 失败需 admin', 'sc delete 回滚', '5秒', 'sc 命令比 net 服务名精确'],
        ['防火墙', '放行应用端口', 'netsh advfirewall', 'netsh 失败', '跳过', '3秒', '需管理员权限'],
        ['计划任务', '开机/定时启动', 'schtasks /create /sc', 'schtasks 失败', 'schtasks /delete', '5秒', '/ru /rp 存储凭据'],
        ['文件关联', '扩展名绑定应用', 'assoc + ftype', 'assoc 失败', '恢复默认', '2秒', 'assoc .ext=ftype_name'],
        ['卸载入口', '控制面板显示', 'HKLM\\Uninstall\\Key', '写注册表失败', '跳过', '1秒', 'DisplayIcon 指向 exe'],
        ['日志记录', '全流程审计', '>> logfile.txt', '磁盘只读提示', '不影响安装', '<1秒', '每步写一条方便排查'],
        ['进度显示', 'ASCII 进度条', 'set /p + 延迟扩展', '不适用', '不适用', '实时', 'ping -n 做伪延迟'],
        ['异常中断', 'Ctrl+C 处理', 'if errorlevel 1 goto :CANCEL', '提示已取消', '已备份可恢复', '即时', 'trap Ctrl+C 靠 if errorlevel'],
        ['清理', '临时文件删除', 'del /q /f /s', '删除失败跳过', '不影响', '1秒', '用 2>nul 抑制错误'],
        ['完成页', '总结 + 启动选项', 'choice /C YN', 'choice 校验', '启动前再确认', '<1秒', '可以显示 "查看日志"'],
        ['静默安装', '无人值守参数', 'if "%~1"=="/S"', '参数校验', '不适用', '跳过UI', '必须支持 /S 参数'],
        ['卸载脚本', '反向安装流程', '保存 backup 信息', '卸载失败提示', '提示手动卸载', '10-30秒', '记录 uninstall.log'],
        ['升级检测', '版本判断', 'wmic qfe / version', '无法读取则跳过', '手动升级', '3秒', '注册表 Version 字段'],
        ['回滚', '从 backup 恢复', 'xcopy /E /Y 反向', '恢复失败警告', '提示手动恢复', '10-30秒', '只回滚已成功的步骤'],
        ['签名验证', '文件完整性校验', 'certutil -hashfile + 比对', '哈希不匹配', '拒绝安装', '2-5秒', 'SHA256 比 MD5 安全'],
    ]
    t2big = Table(_wrap_table_rows(tbl2_data), colWidths=[21.1*mm, 24.6*mm, 31.6*mm, 24.6*mm, 21.1*mm, 14.0*mm, 21.1*mm])
    t2big.setStyle(TableStyle([
        ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#B9770E')),
        ('GRID', (0, 0), (-1, -1), 0.4, colors.HexColor('#D5D8DC')),
        ('ROWBACKGROUNDS', (0, 1), (-1, -1), [colors.white, colors.HexColor('#FEF9E7')]),
        ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
        ('TOPPADDING', (0, 0), (-1, -1), 2),
        ('BOTTOMPADDING', (0, 0), (-1, -1), 2),
        ('LEFTPADDING',   (0, 0), (-1, -1), 6),
        ('RIGHTPADDING',  (0, 0), (-1, -1), 6),
    ]))

    ex[2] = ex[2] + [
        Spacer(1, 20),
        Paragraph('进阶项目2：交互式安装向导模板', ST_SEC_TITLE),
        Paragraph('这个完整的安装向导涵盖了商业安装程序的所有标准阶段：欢迎页、许可协议、目录选择、权限检查、旧版备份、文件复制、快捷方式、注册表写入、PATH 更新、完成页。脚本带完整的错误处理和回滚机制——任何一步失败都不会让系统处于半安装状态。', ST_BODY),
        make_code_block(code2_install),
        Spacer(1, 15),
        Paragraph('安装向导各阶段实现清单（25 项）', ST_SEC_TITLE),
        t2big,
        Spacer(1, 15),
        Paragraph('BAT 写安装程序最大的挑战是权限问题。写到 HKLM 注册表、安装到 Program Files、注册系统服务——这些都需要管理员权限。标准做法是用 net session >nul 2>nul 检测当前是否 admin，如果不是就调用 powershell Start-Process -Verb RunAs 提权重启自身。注意参数传递要用 /c %~f0 %* 保留原参数。', ST_BODY),
        Paragraph('PATH 更新不能直接 set PATH=xxx——那只在当前进程有效。持久化 PATH 要写注册表 HKCU\\Environment\\PATH。读取时也要用 reg query 而不是 %PATH%，否则你读到的是旧值。还要注意 Windows 的 PATH 长度限制是 1024 字符，超过的话 trunc 会丢条目。', ST_BODY),
        Paragraph('安装脚本一定要做旧版备份！用 backup_%random% 作为目录名可以保证唯一不冲突。回滚时只要把备份目录反向 xcopy 回安装目录就行。商业安装程序（如 Inno Setup、NSIS）也都是这个思路——先备份旧文件，再写新文件，失败则恢复。', ST_BODY),
        Paragraph('静默安装（/S 参数）是企业部署的标配。BAT 脚本开头用 if "%~1"=="/S" goto :SILENT 检测，然后跳过所有 choice 和 set /p，自动采用默认值。这种设计让同一个安装包既能交互式安装，又能被 SCCM/GPO/批处理批量部署。', ST_BODY),
        Paragraph('安装日志是出问题后的救命稻草。每一步都用 >> logfile.txt 追加写入，时间戳用 [%date% %time%]。不要用 > 覆盖——一旦中途崩溃就失去所有上下文。日志里要记录"开始某步"、"某步成功"、"某步失败原因"三级信息。', ST_BODY),
    ]

    # ============ ex[3] 第三波：子程序库 - 10 个常用工具函数 ============
    code3_lib = _build_code([
        '@echo off',
        'setlocal enabledelayedexpansion',
        'rem ============================================================',
        'rem  BAT 公共子程序库 - 10 个常用工具函数',
        'rem  用法: 在你的脚本开头 call "%~f0" /LIBRARY 跳过主函数',
        'rem       或者直接把这些 :FunctionName 复制到你的脚本里',
        'rem ============================================================',
        '',
        'rem ========== 主程序入口 ==========',
        'if /i "%~1"=="/LIBRARY" goto :EOF',
        '',
        'echo === BAT 公共子程序库 ===',
        'echo 正在测试 10 个工具函数...',
        'echo.',
        '',
        'call :check_admin result',
        'echo check_admin - 管理员权限: !result!',
        '',
        'call :get_os_ver ver_name ver_num ver_arch',
        'echo get_os_ver - 名称=!ver_name! 版本=!ver_num! 架构=!ver_arch!',
        '',
        'call :log_msg INFO "这是一条 INFO 消息"',
        'call :log_msg WARN "这是一条 WARN 消息"',
        'call :log_msg ERROR "这是一条 ERROR 消息"',
        '',
        'call :safe_copy "%~f0" "%temp%\\test_copy.bat"',
        'echo safe_copy - result=%errorlevel%',
        '',
        'call :file_size "%~f0" size_kb',
        'echo file_size - !size_kb! KB',
        '',
        'call :str_contains "Hello World" "World" contains',
        'echo str_contains - "Hello World" 包含 "World": !contains!',
        '',
        'call :str_trim "   hello   " trimmed',
        'echo str_trim - 原= "   hello   " 去空格后= "!trimmed!"',
        '',
        'call :timestamp ts',
        'echo timestamp - !ts!',
        '',
        'call :rand_int 1 100 rand_val',
        'echo rand_int - 1-100 随机数: !rand_val!',
        '',
        'call :base64_encode "test input" encoded',
        'echo base64_encode - !encoded!',
        '',
        'del /q "%temp%\\test_copy.bat" 2>nul',
        'echo.',
        'echo === 所有函数测试完毕 ===',
        'pause',
        'exit /b',
        '',
        'rem ============================================================',
        'rem 函数 1: check_admin - 检测管理员权限',
        'rem 用法: call :check_admin var_name',
        'rem 返回: 1=管理员, 0=非管理员',
        'rem ============================================================',
        ':check_admin',
        'setlocal',
        'net session >nul 2>&1',
        'set /a admin=0',
        'if !errorlevel! equ 0 set /a admin=1',
        'endlocal & set "%~1=%admin%"',
        'exit /b',
        '',
        'rem ============================================================',
        'rem 函数 2: get_os_ver - 获取操作系统版本信息',
        'rem 用法: call :get_os_ver out_name out_version out_arch',
        'rem ============================================================',
        ':get_os_ver',
        'setlocal',
        'set "_name=Unknown"',
        'set "_ver=Unknown"',
        'set "_arch=%PROCESSOR_ARCHITECTURE%"',
        'for /f "tokens=2 delims==" %%a in (\'wmic os get Caption /format:list 2^>nul ^| findstr Caption\') do set "_name=%%a"',
        'for /f "tokens=2 delims==" %%b in (\'wmic os get Version /format:list 2^>nul ^| findstr Version\') do set "_ver=%%b"',
        'endlocal & set "%~1=%_name%" & set "%~2=%_ver%" & set "%~3=%_arch%"',
        'exit /b',
        '',
        'rem ============================================================',
        'rem 函数 3: log_msg - 带时间戳的日志输出',
        'rem 用法: call :log_msg LEVEL "消息内容"',
        'rem 日志同时输出到控制台和 %LOG_FILE%',
        'rem ============================================================',
        ':log_msg',
        'setlocal',
        'set "_level=%~1"',
        'set "_msg=%~2"',
        'for /f "tokens=*" %%t in (\'time /t\') do set "_time=%%t"',
        'set "_line=[%date% !_time!] [!_level!] !_msg!"',
        'if /i "!_level!"=="ERROR" echo. & echo ^>^>^> !_line! & echo.',
        'if /i not "!_level!"=="ERROR" echo !_line!',
        'if defined LOG_FILE echo !_line! >> "%LOG_FILE%"',
        'endlocal',
        'exit /b',
        '',
        'rem ============================================================',
        'rem 函数 4: safe_copy - 带重试的安全文件复制',
        'rem 用法: call :safe_copy "源路径" "目标路径"',
        'rem 返回: errorlevel 0=成功, 1=失败',
        'rem ============================================================',
        ':safe_copy',
        'setlocal',
        'set "_src=%~1"',
        'set "_dst=%~2"',
        'set /a _retries=3',
        'set /a _delay=2',
        'set /a _attempt=0',
        ':safe_copy_loop',
        'set /a _attempt+=1',
        'if not exist "!_src!" (',
        '    echo [safe_copy] 源文件不存在: !_src!',
        '    endlocal & exit /b 1',
        ')',
        'copy /y "!_src!" "!_dst!" >nul 2>&1',
        'if !errorlevel! equ 0 (',
        '    endlocal & exit /b 0',
        ')',
        'if !_attempt! lss !_retries! (',
        '    echo [safe_copy] 第 !_attempt! 次失败，等待 !_delay! 秒重试...',
        '    ping -n !_delay! 127.0.0.1 >nul',
        '    goto :safe_copy_loop',
        ')',
        'echo [safe_copy] 3 次重试均失败',
        'endlocal & exit /b 1',
        '',
        'rem ============================================================',
        'rem 函数 5: file_size - 获取文件大小',
        'rem 用法: call :file_size "文件路径" out_var',
        'rem 返回: KB 为单位的整数',
        'rem ============================================================',
        ':file_size',
        'setlocal',
        'set "_kb=0"',
        'if exist "%~1" (',
        '    for %%a in ("%~1") do set /a "_kb=%%~za/1024"',
        ')',
        'endlocal & set "%~2=%_kb%"',
        'exit /b',
        '',
        'rem ============================================================',
        'rem 函数 6: str_contains - 子串检测',
        'rem 用法: call :str_contains "原串" "查找" out_var',
        'rem 返回: 1=包含, 0=不包含',
        'rem ============================================================',
        ':str_contains',
        'setlocal',
        'set "_hay=%~1"',
        'set "_needle=%~2"',
        'set "_result=0"',
        'echo "!_hay!" | find /i "!_needle!" >nul 2>&1',
        'if !errorlevel! equ 0 set "_result=1"',
        'endlocal & set "%~3=%_result%"',
        'exit /b',
        '',
        'rem ============================================================',
        'rem 函数 7: str_trim - 去除首尾空格',
        'rem 用法: call :str_trim "  hello  " out_var',
        'rem ============================================================',
        ':str_trim',
        'setlocal',
        'set "_s=%~1"',
        ':trim_left',
        'if "!_s:~0,1!"==" " set "_s=!_s:~1!" & goto :trim_left',
        ':trim_right',
        'if "!_s:~-1!"==" " set "_s=!_s:~0,-1!" & goto :trim_right',
        'endlocal & set "%~2=%_s%"',
        'exit /b',
        '',
        'rem ============================================================',
        'rem 函数 8: timestamp - 生成时间戳字符串',
        'rem 用法: call :timestamp out_var',
        'rem 返回: 20261110_143025 格式',
        'rem ============================================================',
        ':timestamp',
        'setlocal',
        'set "_ts=%date:~0,4%%date:~5,2%%date:~8,2%_%time:~0,2%%time:~3,2%%time:~6,2%"',
        'set "_ts=!_ts: =0!"',
        'endlocal & set "%~1=%_ts%"',
        'exit /b',
        '',
        'rem ============================================================',
        'rem 函数 9: rand_int - 生成范围内随机整数',
        'rem 用法: call :rand_int min max out_var',
        'rem ============================================================',
        ':rand_int',
        'setlocal',
        'set /a _min=%~1',
        'set /a _max=%~2',
        'set /a _range=_max-_min+1',
        'set /a _val=%random% %% _range + _min',
        'endlocal & set "%~3=%_val%"',
        'exit /b',
        '',
        'rem ============================================================',
        'rem 函数 10: base64_encode - Base64 编码字符串',
        'rem 用法: call :base64_encode "内容" out_var',
        'rem ============================================================',
        ':base64_encode',
        'setlocal',
        'set "_tmp=%temp%\\b64_in_%random%.txt"',
        'echo|set /p "=%~1" > "!_tmp!"',
        'set "_encoded="',
        'for /f "usebackq delims=" %%l in (`certutil -encode "!_tmp!" ^| findstr /v /c:"-----"`) do (',
        '    set "_encoded=!_encoded!%%l"',
        ')',
        'del /q "!_tmp!"',
        'endlocal & set "%~2=%_encoded%"',
        'exit /b',
    ])
    tbl3_data = [
        ['函数名', '用途', '参数', '返回值', '实现原理', '依赖', '典型调用', '注意事项'],
        ['check_admin', '检测管理员权限', '(out_var)', '1=admin 0=no', 'net session >nul 返回码', '无', 'call :check_admin is_admin', 'HKLM 操作前必调'],
        ['get_os_ver', '获取 OS 版本详情', '(out_name out_ver out_arch)', '三个变量', 'wmic os get 三个字段', 'wmic', 'call :get_os_ver n v a', 'wmic 可能被安全软件禁用'],
        ['log_msg', '带时间戳的日志', 'LEVEL "msg"', '无（写 stdout+文件）', 'echo + 时间拼接', '无', 'call :log_msg INFO "ok"', '需先 set LOG_FILE'],
        ['safe_copy', '带重试的复制', '"src" "dst"', 'errorlevel', 'copy + for 循环重试', 'copy', 'call :safe_copy a.txt b.txt', '3次重试，ping 延迟'],
        ['file_size', '文件大小(KB)', '"path" out_var', 'KB 整数', '%%~za / 1024', 'for %%, dir', 'call :file_size a.txt size', '%%~za 返回字节'],
        ['str_contains', '子串检测', '"hay" "needle" out', '1/0', 'echo | find /i', 'find', 'call :str_contains abcd bc r', 'find 忽略大小写用 /i'],
        ['str_trim', '去首尾空格', '"  s  " out_var', '去空格后的串', '循环 :~0,1! 逐个弹掉', '延迟扩展', 'call :str_trim " x " r', '只能去半角空格'],
        ['timestamp', '生成时间戳', 'out_var', 'YYYYMMDD_HHMMSS', 'date/time 子串拼接', '无', 'call :timestamp ts', 'date 格式依赖系统区域'],
        ['rand_int', '范围随机整数', 'min max out_var', '范围内整数', '%random% %% range', '%random%', 'call :rand_int 1 10 r', '模运算小偏差可接受'],
        ['base64_encode', 'Base64 编码', '"str" out_var', '编码串', 'certutil -encode 临时文件', 'certutil', 'call :base64_encode hi r', 'certutil 是原生工具'],
        ['base64_decode', 'Base64 解码', '"b64" out_var', '原串', 'certutil -decode 临时文件', 'certutil', 'call :base64_decode aGVsbG8= r', '先写临时文件再解'],
        ['str_replace', '子串替换', '"s" "old" "new" out', '替换后字符串', '!s:old=new! 内置替换', '延迟扩展', 'call :str_replace ab a x r', 'BAT 原生支持，最安全'],
        ['file_ext', '提取文件扩展名', '"path" out_var', '扩展名含点', '%%~x 修饰符', 'for %%, cmd', 'call :file_ext file.zip e', '%%~x 包括点号'],
        ['file_dir', '提取目录部分', '"path" out_var', '目录含 \\', '%%~dp 修饰符', 'for %%, cmd', 'call :file_dir C:\\a\\b d', '%%~dp 末尾有反斜杠'],
        ['path_join', '拼接路径段', '"a" "b" out_var', 'a\\b', '简单字符串拼接', '无', 'call :path_join C:\\ a\\b r', '注意双反斜杠'],
        ['is_dir', '判断目录存在', '"path" out_var', '1=存在 0=不存在', 'if exist "path\\"', 'cmd', 'call :is_dir C:\\ a r', '目录末尾加 \\'],
        ['is_file', '判断文件存在', '"path" out_var', '1=存在 0=不存在', 'if exist "path"', 'cmd', 'call :is_file a.txt r', '不加尾部斜杠'],
        ['sleep', '指定秒数等待', 'seconds', '无（暂停）', 'ping -n N 127.0.0.1', 'ping', 'call :sleep 5', '精度约 ±0.5 秒'],
        ['get_free_port', '找空闲端口', 'start_port out_var', '可用端口号', 'for /L + netstat findstr', 'netstat', 'call :get_free_port 10000 p', '逐个测试直到空'],
        ['sha256', '计算文件哈希', '"path" out_var', 'SHA256 串', 'certutil -hashfile', 'certutil', 'call :sha256 a.txt h', '输出需 findstr /v certutil'],
        ['dir_size', '目录总大小', '"path" out_var', 'MB 整数', 'for /R + 累加 %%~za', '延迟扩展', 'call :dir_size C:\\Dir s', '大目录可能慢'],
        ['grep_count', '统计匹配行数', '"pattern" "file" out_var', '行数', 'find /c /v "" + find', 'find', 'call :grep_count error log.txt c', '/c /v "" 是行数技巧'],
        ['ini_read', '读 INI 配置', '"file" section key out', '值', 'for /f 解析 ini 格式', 'for /f', 'call :ini_read c.ini DB host r', '用 [section] 过滤'],
        ['clip_set', '写入剪贴板', '"text"', '无', 'echo | clip', 'clip', 'call :clip_set "hi"', 'clip 是 Windows 自带'],
        ['http_get', 'HTTP GET 请求', 'URL out_var', '响应体', 'curl -s -o -', 'curl 或 PS', 'call :http_get url body', 'Windows 10+ 自带 curl'],
    ]
    t3big = Table(_wrap_table_rows(tbl3_data), colWidths=[17.0*mm, 21.5*mm, 19.8*mm, 17.0*mm, 21.5*mm, 14.2*mm, 25.5*mm, 21.5*mm])
    t3big.setStyle(TableStyle([
        ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#7D6608')),
        ('GRID', (0, 0), (-1, -1), 0.4, colors.HexColor('#D5D8DC')),
        ('ROWBACKGROUNDS', (0, 1), (-1, -1), [colors.white, colors.HexColor('#FEF9E7')]),
        ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
        ('TOPPADDING', (0, 0), (-1, -1), 2),
        ('BOTTOMPADDING', (0, 0), (-1, -1), 2),
        ('LEFTPADDING',   (0, 0), (-1, -1), 6),
        ('RIGHTPADDING',  (0, 0), (-1, -1), 6),
    ]))

    ex[3] = ex[3] + [
        Spacer(1, 20),
        Paragraph('进阶项目3：子程序库 - 10 个常用工具函数', ST_SEC_TITLE),
        Paragraph('这是一份可以直接放进你的每个 BAT 脚本的公共子程序库。10 个函数覆盖了 BAT 开发中最高频的操作：检测管理员、获取系统版本、日志输出、安全复制（带重试）、文件大小、子串检测、字符串处理、时间戳、随机数、Base64 编码。每个函数都设计成 endlocal & set 的经典传值模式。', ST_BODY),
        make_code_block(code3_lib),
        Spacer(1, 15),
        Paragraph('可复用子程序清单（25 个扩展函数）', ST_SEC_TITLE),
        t3big,
        Spacer(1, 15),
        Paragraph('写 BAT 子程序最重要的是参数传递和返回值。BAT 没有真正的函数参数，靠 %~1、%~2 位置取值；返回值靠 endlocal & set trick——因为 BAT 解析器会先把整行的 %var% 展开，这时 endlocal 还没执行，所以值能"漏出"作用域。这是 BAT 唯一安全的传值办法。', ST_BODY),
        Paragraph('safe_copy 里的 ping 延迟技巧（ping -n 5 127.0.0.1 >nul）是 BAT 实现 sleep 的标准 hack。timeout /t 也能用但会显示倒计时，ping 更静默。精度大约 ±0.5 秒，足够重试场景用。真正精确的延迟要用 PowerShell Start-Sleep -Milliseconds。', ST_BODY),
        Paragraph('这个函数库还可以扩展：目录递归大小计算、INI 文件读写、HTTP 下载（用 PowerShell Invoke-WebRequest）、剪贴板操作（clip）、压缩解压（certutil + 临时文件）。但有些场景用 PowerShell 反而比 BAT 本身更简洁——BAT + PowerShell 混合调用才是王道。', ST_BODY),
        Paragraph('函数库的组织方式：主脚本开头加 if /i "%~1"=="/LIBRARY" goto :EOF，这样其他脚本可以 call library.bat /LIBRARY 来加载所有子程序定义而不执行主程序。这是 BAT 实现 import/模块化的经典手法。', ST_BODY),
    ]

    # ============ ex[4] 第三波：配置文件解析器 ============
    code4_ini = _build_code([
        '@echo off',
        'setlocal enabledelayedexpansion',
        'title 完整的 INI 配置文件解析器',
        '',
        'rem ============================================================',
        'rem  完整的 INI 配置文件解析器',
        'rem  从 ini 文件读取 key=value 对，支持默认值、类型转换',
        'rem  支持 [section] 分组、注释行、空行跳过',
        'rem  用法: call :ini_read "config.ini" section key out_var default',
        'rem ============================================================',
        '',
        'rem 创建示例 INI 文件',
        '(',
        '    echo ; 这是注释行',
        '    echo # 也是注释',
        '    echo [database]',
        '    echo host=localhost',
        '    echo port=3306',
        '    echo username=root',
        '    echo password=secret123',
        '    echo database=myapp',
        '    echo.',
        '    echo [server]',
        '    echo bind=0.0.0.0',
        '    echo port=8080',
        '    echo max_connections=100',
        '    echo debug=false',
        '    echo timeout=30',
        '    echo.',
        '    echo [paths]',
        '    echo data_dir=C:\\ProgramData\\MyApp',
        '    echo log_dir=C:\\Logs\\MyApp',
        '    echo temp_dir=%%TEMP%%\\MyApp',
        '    echo.',
        '    echo [features]',
        '    echo enable_ssl=true',
        '    echo enable_cache=yes',
        '    echo compression=on',
        '    echo max_retries=5',
        ') > sample.ini',
        '',
        'echo === 解析示例 INI 文件 ===',
        'echo.',
        '',
        'call :ini_read "sample.ini" database host db_host',
        'call :ini_read "sample.ini" database port db_port 3306',
        'call :ini_read "sample.ini" database username db_user',
        'call :ini_read "sample.ini" database password db_pwd',
        'call :ini_read "sample.ini" database database db_name',
        'echo [database] section:',
        'echo   host=!db_host!',
        'echo   port=!db_port!',
        'echo   username=!db_user!',
        'echo   password=!db_pwd!',
        'echo   database=!db_name!',
        'echo.',
        '',
        'call :ini_read "sample.ini" server bind srv_bind',
        'call :ini_read "sample.ini" server port srv_port',
        'call :ini_read "sample.ini" server max_connections srv_maxconn',
        'call :ini_read "sample.ini" server debug srv_debug',
        'call :ini_read "sample.ini" server timeout srv_timeout',
        'echo [server] section:',
        'echo   bind=!srv_bind!',
        'echo   port=!srv_port!',
        'echo   max_connections=!srv_maxconn!',
        'echo   debug=!srv_debug!',
        'echo   timeout=!srv_timeout!',
        'echo.',
        '',
        'call :ini_read "sample.ini" features enable_ssl feat_ssl',
        'call :ini_read "sample.ini" features enable_cache feat_cache',
        'call :ini_read "sample.ini" features missing_key feat_missing 这里是默认值',
        'echo [features] section:',
        'echo   enable_ssl=!feat_ssl!',
        'echo   enable_cache=!feat_cache!',
        'echo   missing_key=!feat_missing!  ^(应该是默认值^)',
        'echo.',
        '',
        'echo === 验证布尔值解析 ===',
        'call :ini_read_bool "sample.ini" server debug is_debug',
        'echo server.debug 布尔值: !is_debug!',
        'call :ini_read_bool "sample.ini" features enable_ssl has_ssl',
        'echo features.enable_ssl 布尔值: !has_ssl!',
        'echo.',
        '',
        'echo === 遍历整个 INI 文件 ===',
        'call :ini_dump "sample.ini"',
        '',
        'del sample.ini',
        'echo.',
        'pause',
        'exit /b',
        '',
        'rem ============================================================',
        'rem :ini_read - 读取单个配置值',
        'rem 参数: "%1"=文件路径 %2=section %3=key %4=out_var %5=默认值(可选)',
        'rem ============================================================',
        ':ini_read',
        'setlocal',
        'set "_file=%~1"',
        'set "_section=%~2"',
        'set "_key=%~3"',
        'set "_result="',
        'if "%~5" neq "" set "_result=%~5"',
        'set "_cur_section="',
        'if not exist "!_file!" goto :ini_read_done',
        'for /f "usebackq tokens=1,* delims==" %%a in ("!_file!") do (',
        '    set "_line=%%a"',
        '    rem 跳过空行',
        '    if not "!_line!"=="" (',
        '        rem 跳过注释行',
        '        if "!_line:~0,1!"==";" goto :ini_read_continue',
        '        if "!_line:~0,1!"=="#" goto :ini_read_continue',
        '        rem 检测 section 头',
        '        if "!_line:~0,1!"=="[" (',
        '            set "_cur_section=!_line:~1,-1!"',
        '        ) else (',
        '            rem 匹配 section 和 key',
        '            if /i "!_cur_section!"=="!_section!" (',
        '                if /i "%%a"=="!_key!" (',
        '                    set "_result=%%b"',
        '                )',
        '            )',
        '        )',
        '    )',
        '    :ini_read_continue',
        ')',
        ':ini_read_done',
        'endlocal & set "%~4=%_result%"',
        'exit /b',
        '',
        'rem ============================================================',
        'rem :ini_read_bool - 读取并解析布尔值',
        'rem ============================================================',
        ':ini_read_bool',
        'setlocal',
        'call :ini_read "%~1" "%~2" "%~3" _raw_val',
        'set "_bool=0"',
        'if /i "!_raw_val!"=="true" set "_bool=1"',
        'if /i "!_raw_val!"=="yes" set "_bool=1"',
        'if /i "!_raw_val!"=="on" set "_bool=1"',
        'if "!_raw_val!"=="1" set "_bool=1"',
        'endlocal & set "%~4=%_bool%"',
        'exit /b',
        '',
        'rem ============================================================',
        'rem :ini_dump - 遍历并打印整个 INI 文件',
        'rem ============================================================',
        ':ini_dump',
        'setlocal',
        'set "_file=%~1"',
        'set "_cur_section="',
        'echo 配置文件内容:',
        'for /f "usebackq tokens=1,* delims==" %%a in ("!_file!") do (',
        '    set "_line=%%a"',
        '    if not "!_line!"=="" (',
        '        if "!_line:~0,1!"=="[" (',
        '            echo.',
        '            echo [!_line:~1,-1!]',
        '        ) else (',
        '            if not "!_line:~0,1!"==";" (',
        '                if not "!_line:~0,1!"=="#" (',
        '                    echo   %%a = %%b',
        '                )',
        '            )',
        '        )',
        '    )',
        ')',
        'endlocal',
        'exit /b',
    ])
    tbl4_data = [
        ['INI 解析要点', '问题', '解决方案', 'BAT 实现方式', '可靠性', '性能'],
        ['注释行跳过', '; 和 # 两种注释', '两种前缀都检测', 'if "!line:~0,1!"==";"', '高', 'O(n)'],
        ['Section 分组', '[section] 格式', '切 [ 和 ] 取中间', '!_line:~1,-1!', '高', 'O(1)'],
        ['key=value 拆分', '等号可能含多个', '用 delims== 拆，tokens=1,*', 'for /f delims==', '高', 'O(1)'],
        ['value 含等号', 'a=b=c=d', 'tokens=1,* 把后面全算 value', 'tokens=1,* delims==', '高', 'O(1)'],
        ['空行处理', 'ini 文件有空行', 'if not "!_line!"==""', '空字符串判断', '高', 'O(1)'],
        ['默认值支持', 'key 不存在时', '函数第 5 参数作为默认值', 'if "%~5" neq ""', '高', 'O(1)'],
        ['大小写不敏感', 'Host vs host', 'if /i 比较 section 和 key', 'if /i "!cur!"=="!target!"', '高', 'O(1)'],
        ['布尔值解析', 'true/yes/on/1', '四种真值统一映射', '四个 if /i 判断', '高', 'O(1)'],
        ['数字校验', 'port 必须数字', 'echo !val!|findstr /r "^[0-9]*$"', '正则 findstr', '中', 'O(n)'],
        ['文件编码', 'UTF-8 vs ANSI', '统一保存为 ANSI(GBK)', 'chcp 936', '高', 'O(1)'],
        ['变量展开', '%TEMP% 这类', 'BAT 默认会展开', 'setlocal + !var!', '高', 'O(1)'],
        ['路径中的反斜杠', 'C:\\Dir', '直接读入不转义', '保留原值', '高', 'O(1)'],
        ['等号周围空格', 'key = value', '手动 trim 空格', '循环去首尾空格', '中', 'O(k)'],
        ['嵌套引号', '"quoted value"', '读入后去掉首尾引号', 'if "!v:~0,1!"=="""', '中', 'O(1)'],
        ['多值列表', 'ports=80,443', '用 for 循环拆分', 'for /f delims=,', '高', 'O(n)'],
        ['缺省 Section', 'key 在任何 section 外', '先匹配无 section 情况', 'cur_section="" 特殊判断', '中', 'O(1)'],
        ['重复 key', '同一个 key 多次出现', '取最后一次出现', '顺序覆盖赋值', '高', 'O(n)'],
        ['文件不存在', '配置文件丢失', 'ini_read 返回默认值', 'if not exist 先判断', '高', 'O(1)'],
        ['大文件性能', 'ini 超过几百行', 'BAT for /f 逐行扫描', '一次性扫描 O(n)', '中', 'O(n)'],
        ['热更新', '运行时改 ini', '需要重新 call ini_read', '每次读都扫文件', '低', 'O(n)'],
        ['多 Section 同 key', '不同 section 同名 key', '用 section+key 定位', '两重判断', '高', 'O(1)'],
        ['ini_write 写回', '修改配置', 'BAT 原生不支持，需重建文件', '读-改-写 三阶段', '低', 'O(n)'],
        ['INI vs 注册表', '配置放哪', 'ini 方便查看/备份', 'HKCU\\Software\\App 也可以', '中', '看场景'],
        ['JSON 替代', '更复杂配置', '用 PowerShell ConvertFrom-Json', 'powershell -Command', '高', '中'],
        ['YAML 替代', '层级配置', 'BAT 难解析，建议用 PS/Python', 'powershell 第三方模块', '高', '中'],
    ]
    t4big = Table(_wrap_table_rows(tbl4_data), colWidths=[22.9*mm, 32.7*mm, 32.7*mm, 45.0*mm, 12.3*mm, 12.3*mm])
    t4big.setStyle(TableStyle([
        ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#2E86C1')),
        ('GRID', (0, 0), (-1, -1), 0.4, colors.HexColor('#D5D8DC')),
        ('ROWBACKGROUNDS', (0, 1), (-1, -1), [colors.white, colors.HexColor('#EBF5FB')]),
        ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
        ('TOPPADDING', (0, 0), (-1, -1), 2),
        ('BOTTOMPADDING', (0, 0), (-1, -1), 2),
        ('LEFTPADDING',   (0, 0), (-1, -1), 6),
        ('RIGHTPADDING',  (0, 0), (-1, -1), 6),
    ]))

    ex[4] = ex[4] + [
        Spacer(1, 20),
        Paragraph('进阶项目4：配置文件解析器', ST_SEC_TITLE),
        Paragraph('这个完整的 INI 解析器实现了所有标准功能：section 分组、key=value 读取、默认值、注释跳过（; 和 #）、布尔值解析、大小写不敏感匹配。整个解析器只用 50 行 BAT 实现，核心是 for /f + usebackq + 延迟扩展的经典组合。', ST_BODY),
        make_code_block(code4_ini),
        Spacer(1, 15),
        Paragraph('INI 解析实现要点汇总（25 项）', ST_SEC_TITLE),
        t4big,
        Spacer(1, 15),
        Paragraph('BAT 解析 ini 文件的核心难点在于 for /f 的 usebackq 模式——没有它双引号文件名会被当成字符串字面量。tokens=1,* delims== 这个写法是关键：tokens=1 取 key，* 把剩余所有（包括后续的等号和值）合并成 %%b。这样值里有多个等号也不会被截断。', ST_BODY),
        Paragraph('注释跳过用前缀匹配 !_line:~0,1!，先检查 ; 和 #，然后检测 section 头 [。这种"逐行扫描+状态变量追踪当前 section"的模式是 BAT 解析所有结构化文本的通用套路——无论是 ini、csv、log 还是自定义格式，都是同一套框架。', ST_BODY),
        Paragraph('写回 ini（ini_write）是 BAT 不擅长的事。因为 BAT 没有 insert/delete 行的能力，要修改就必须整文件读进来、改数组、再整文件写出去。建议复杂配置用 PowerShell 直接操作 JSON 或注册表，BAT 里只管读配置然后调用对应的工具。', ST_BODY),
    ]

    # ============ ex[5] 第三波：文件搜索器 - 递归遍历 ============
    code5_search = _build_code([
        '@echo off',
        'setlocal enabledelayedexpansion',
        'title 递归文件搜索器 v1.0',
        '',
        'rem ============================================================',
        'rem  递归文件搜索器',
        'rem  按扩展名、大小、日期过滤，支持排除目录',
        'rem  支持搜索结果导出 CSV / TXT',
        'rem ============================================================',
        '',
        'rem ========== 参数解析 ==========',
        'set "SEARCH_DIR=%~1"',
        'if "!SEARCH_DIR!"=="" set "SEARCH_DIR=."',
        'set "EXT_FILTER=%~2"',
        'if "!EXT_FILTER!"=="" set "EXT_FILTER=*"',
        'set "MIN_SIZE=%~3"',
        'if "!MIN_SIZE!"=="" set "MIN_SIZE=0"',
        'set "MAX_SIZE=%~4"',
        'if "!MAX_SIZE!"=="" set "MAX_SIZE=999999999"',
        'set "OUTPUT=search_result_%date:~0,4%%date:~5,2%%date:~8,2%.csv"',
        '',
        'rem ========== 排除目录列表（可在这里追加） ==========',
        'set "EXCLUDE_DIRS=node_modules .git .svn __pycache__ temp tmp dist build bin obj"',
        '',
        'echo === 递归文件搜索器 ===',
        'echo 搜索目录: !SEARCH_DIR!',
        'echo 扩展名:   !EXT_FILTER!',
        'echo 最小大小: !MIN_SIZE! KB',
        'echo 最大大小: !MAX_SIZE! KB',
        'echo 排除目录: !EXCLUDE_DIRS!',
        'echo 输出文件: !OUTPUT!',
        'echo.',
        '',
        'rem ========== 检查目录 ==========',
        'if not exist "!SEARCH_DIR!" (',
        '    echo [错误] 目录不存在: !SEARCH_DIR!',
        '    pause',
        '    exit /b 1',
        ')',
        '',
        'rem ========== 写 CSV 表头 ==========',
        'echo "文件名","完整路径","大小(KB)","修改时间" > "!OUTPUT!"',
        '',
        'set /a total=0',
        'set /a matched=0',
        'set /a total_size=0',
        '',
        'echo 正在扫描...',
        'call :ScanDir "!SEARCH_DIR!"',
        '',
        'echo.',
        'echo ========== 搜索完成 ==========',
        'echo 扫描文件总数: !total!',
        'echo 匹配文件数:   !matched!',
        'echo 匹配总大小:   !total_size! KB',
        'echo 结果已保存到: !OUTPUT!',
        'echo.',
        'choice /C YN /M "是否打开结果文件"',
        'if errorlevel 1 start "" notepad "!OUTPUT!"',
        'endlocal',
        'pause',
        'exit /b',
        '',
        'rem ============================================================',
        ':ScanDir',
        'set "_cur=%~1"',
        'rem 先列出当前目录下的文件',
        'for %%f in ("!_cur!\\!EXT_FILTER!") do (',
        '    set /a total+=1',
        '    if !errorlevel! equ 0 (',
        '        call :CheckFile "%%f"',
        '    )',
        ')',
        'rem 再递归子目录',
        'for /d %%d in ("!_cur!\\*") do (',
        '    set "_skip=0"',
        '    set "_name=%%~nd"',
        '    for %%e in (!EXCLUDE_DIRS!) do (',
        '        if /i "!_name!"=="%%e" set "_skip=1"',
        '    )',
        '    if !_skip! equ 0 call :ScanDir "%%d"',
        ')',
        'exit /b',
        '',
        'rem ============================================================',
        ':CheckFile',
        'set "_f=%~1"',
        'rem 获取大小',
        'for %%a in ("!_f!") do (',
        '    set /a "_kb=%%~za/1024" 2>nul',
        '    set "_name=%%~nxa"',
        '    set "_path=%%~fa"',
        '    set "_mtime=%%~ta"',
        ')',
        'if "!_kb!"=="" set /a _kb=0',
        'rem 大小过滤',
        'if !_kb! lss !MIN_SIZE! exit /b',
        'if !_kb! gtr !MAX_SIZE! exit /b',
        'rem 匹配成功',
        'set /a matched+=1',
        'set /a total_size+=!_kb!',
        'echo "!_name!","!_path!","!_kb!","!_mtime!" >> "!OUTPUT!"',
        'exit /b',
    ])
    tbl5_data = [
        ['搜索维度', '说明', 'BAT 实现', '速度', '精度', '灵活度', '备注'],
        ['按文件名', '通配符匹配 *.py', 'for /R 配合 *', '快', '高', '高', '最常用的搜索'],
        ['按扩展名', '*.bat / *.txt', 'for /R * 再 %%~x 判断', '快', '高', '高', '直接写通配符'],
        ['按大小(精确)', '恰好多少字节', '%%~za 直接取', '快', '高', '中', 'BAT 原生支持'],
        ['按大小(范围)', '100KB-1MB', 'if /lss /gtr %%~za', '快', '高', '高', '数学比较'],
        ['按修改时间', '最近 7 天', '用 forfiles /d -7', '中', '高', '中', 'Windows 自带'],
        ['按创建时间', '创建时间过滤', 'forfiles 不直接支持', '中', '中', '低', '需 PowerShell'],
        ['按内容(文本)', '包含某个字符串', 'findstr /s /m', '慢', '中', '中', '二进制文件会乱码'],
        ['按内容(正则)', '高级内容匹配', 'findstr /r /s', '慢', '高', '高', '支持有限正则'],
        ['按属性', '隐藏/系统/只读', 'attrib + for', '中', '高', '低', '需 attrib 配合'],
        ['按所有者', '用户/组过滤', 'icacls 或 dir /q', '慢', '高', '低', '需要额外工具'],
        ['递归深度限制', '只搜 3 层', '手动计数或 robocopy', '中', '高', '中', 'BAT 原生不支持'],
        ['排除目录', '跳过 node_modules', 'for /d + if /i 跳过', '中', '高', '高', '最实用的优化'],
        ['排除隐藏文件', '.开头或 H 属性', 'dir /a:-h', '快', '高', '中', '/a:h 只显示隐藏'],
        ['多扩展名', 'bat,cmd,ps1', '多个 for 或 *.b*', '慢', '高', '低', 'BAT 不支持 OR 过滤'],
        ['正则文件名', 'a.*c$', 'findstr /r 配合 dir /b', '慢', '中', '高', '迂回实现'],
        ['UTF-8 文件名', '中文/日文', 'chcp 65001', '中', '中', '高', '编码问题小心'],
        ['长路径支持', '>260 字符', '\\?\\ 前缀', '快', '高', '低', 'Windows 10+ 默认开'],
        ['符号链接', 'junction/symlink', 'dir /a:L /b', '快', '中', '中', '会递归死循环'],
        ['压缩文件内部', 'zip/rar 内容', '需要 7z / tar', '慢', '高', '低', 'BAT 原生不支持'],
        ['空文件', '0 字节检测', 'if %%~za==0', '快', '高', '高', '容易漏的检查'],
        ['临时文件清理', '*.tmp / *.bak', '多通配符搜索+del', '快', '高', '高', '常见清理脚本'],
        ['重复文件', '哈希比对去重', 'certutil -hashfile + 比对', '极慢', '高', '低', '大目录慎用'],
        ['文件计数统计', '某类型有多少个', 'for /R + set /a count+=1', '中', '高', '中', '配合延迟扩展'],
        ['导出 CSV', '供 Excel 分析', 'echo "a","b","c" > file.csv', '快', '高', '高', '加双引号防逗号'],
        ['实时监控', '文件变化通知', 'BAT 难实现，用 PowerShell IO.FileWatcher', '慢', '低', '极低', 'BAT 不适合实时'],
    ]
    t5big = Table(_wrap_table_rows(tbl5_data), colWidths=[25.0*mm, 27.4*mm, 43.0*mm, 11.7*mm, 11.7*mm, 11.7*mm, 27.4*mm])
    t5big.setStyle(TableStyle([
        ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#1E8449')),
        ('GRID', (0, 0), (-1, -1), 0.4, colors.HexColor('#D5D8DC')),
        ('ROWBACKGROUNDS', (0, 1), (-1, -1), [colors.white, colors.HexColor('#E8F8F5')]),
        ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
        ('TOPPADDING', (0, 0), (-1, -1), 2),
        ('BOTTOMPADDING', (0, 0), (-1, -1), 2),
        ('LEFTPADDING',   (0, 0), (-1, -1), 6),
        ('RIGHTPADDING',  (0, 0), (-1, -1), 6),
    ]))

    ex[5] = ex[5] + [
        Spacer(1, 20),
        Paragraph('进阶项目5：文件搜索器 - 递归遍历', ST_SEC_TITLE),
        Paragraph('这个递归搜索器实现了 BAT 能做的所有文件搜索功能：按扩展名通配符、按大小范围过滤（KB 为单位）、按扩展名列表排除目录、CSV 导出结果。核心逻辑是 ScanDir 递归子目录 + CheckFile 匹配大小过滤，经典的"递归+回调"结构。', ST_BODY),
        make_code_block(code5_search),
        Spacer(1, 15),
        Paragraph('文件搜索 25 个维度实现方案', ST_SEC_TITLE),
        t5big,
        Spacer(1, 15),
        Paragraph('BAT 做文件搜索的核心是 for /R 递归遍历，配合 %%~xa 取扩展名、%%~za 取字节大小、%%~ta 取时间戳。for /R 比手动用 for /d 递归子目录简单得多，但缺少排除目录能力——如果项目里有 node_modules 或 .git 这种大目录必须手动跳过，否则性能暴跌。', ST_BODY),
        Paragraph('按内容搜索的利器是 findstr /s /m：/s 递归子目录、/m 只输出文件名（不显示匹配行）。findstr 还支持正则 /r，但语法很简陋（不支持 +、?、分组等）。内容搜索速度比文件名过滤慢 10-100 倍，大目录慎用。', ST_BODY),
        Paragraph('CSV 导出要记得字段加双引号——如果路径里有逗号（罕见但可能），不加引号 Excel 会拆列。同时用 %%~fa 获取完整路径（包括驱动器号），而不是 %%~dpna。时间戳 %%~ta 格式依赖系统区域，导出后可能需要 PowerShell 统一成 ISO 格式。', ST_BODY),
    ]

    # ============ ex[6] 第三波：日志收集器 ============
    code6_log = _build_code([
        '@echo off',
        'setlocal enabledelayedexpansion',
        'title 系统日志收集与分析器',
        '',
        'rem ============================================================',
        'rem  日志收集器 - 收集系统/应用/安全事件日志',
        'rem  按级别过滤（Critical/Error/Warning/Info）',
        'rem  输出：控制台摘要 + CSV 文件 + 错误报告',
        'rem ============================================================',
        '',
        'set "OUT_DIR=%~dp0log_report_%date:~0,4%%date:~5,2%%date:~8,2%"',
        'mkdir "!OUT_DIR!" 2>nul',
        'set "SUMMARY=!OUT_DIR!\\summary.txt"',
        'set "ERROR_LOG=!OUT_DIR!\\errors.csv"',
        'set "WARN_LOG=!OUT_DIR!\\warnings.csv"',
        '',
        'echo === 系统日志收集与分析 ===',
        'echo 输出目录: !OUT_DIR!',
        'echo.',
        '',
        'echo === 1. 系统事件日志 ===',
        'echo 正在收集 System 日志（最近 200 条）...',
        'echo "时间","来源","ID","级别","消息" > "!ERROR_LOG!"',
        'wmic ntevent where "Logfile=\'System\'" get TimeGenerated,SourceName,EventIdentifier,EventType,Message /format:csv > "!OUT_DIR!\\system_raw.csv" 2>nul',
        'set /a sys_count=0',
        'set /a sys_error=0',
        'set /a sys_warn=0',
        'set /a sys_info=0',
        'for /f "usebackq tokens=1,2,3,4,5,* delims=," %%a in ("!OUT_DIR!\\system_raw.csv") do (',
        '    if "%%a" neq "Node" (',
        '        set /a sys_count+=1',
        '        set "_level=%%d"',
        '        if "!_level!"=="2" (set /a sys_error+=1)',
        '        if "!_level!"=="3" (set /a sys_warn+=1)',
        '        if "!_level!"=="4" (set /a sys_info+=1)',
        '    )',
        ')',
        'echo System 日志: 总计 !sys_count! 条, Error=!sys_error!, Warning=!sys_warn!, Info=!sys_info!',
        'echo.',
        '',
        'echo === 2. 应用程序事件日志 ===',
        'wmic ntevent where "Logfile=\'Application\'" get TimeGenerated,SourceName,EventIdentifier,EventType,Message /format:csv > "!OUT_DIR!\\app_raw.csv" 2>nul',
        'set /a app_count=0',
        'set /a app_error=0',
        'set /a app_warn=0',
        'for /f "usebackq tokens=1 delims=," %%a in ("!OUT_DIR!\\app_raw.csv") do (',
        '    if "%%a" neq "Node" set /a app_count+=1',
        ')',
        'echo Application 日志: 总计 !app_count! 条',
        'echo.',
        '',
        'echo === 3. 安全事件日志 ===',
        'rem 安全日志需要管理员权限，用 PowerShell Get-WinEvent 更可靠',
        'powershell -Command "Get-WinEvent -LogName Security -MaxEvents 100 -ErrorAction SilentlyContinue | Select-Object TimeCreated,Id,LevelDisplayName,Message | Export-Csv -Path \'!OUT_DIR!\\security.csv\' -NoTypeInformation"',
        'if exist "!OUT_DIR!\\security.csv" (',
        '    echo Security 日志: 已导出（需要管理员权限才能完整读取）',
        ') else (',
        '    echo Security 日志: 非管理员权限，跳过',
        ')',
        'echo.',
        '',
        'echo === 4. 收集系统信息日志 ===',
        'echo 系统信息:',
        'systeminfo > "!OUT_DIR!\\systeminfo.txt" 2>&1',
        'echo 已导出 systeminfo.txt',
        '',
        'echo 驱动列表:',
        'driverquery /v /fo csv > "!OUT_DIR!\\drivers.csv" 2>&1',
        'echo 已导出 drivers.csv',
        '',
        'echo 已安装补丁:',
        'wmic qfe get /format:csv > "!OUT_DIR!\\hotfixes.csv" 2>&1',
        'echo 已导出 hotfixes.csv',
        '',
        'echo 最近启动程序:',
        'reg query "HKLM\\Software\\Microsoft\\Windows\\CurrentVersion\\Run" > "!OUT_DIR!\\runkeys.txt" 2>&1',
        'echo 已导出 runkeys.txt',
        '',
        'echo 计划任务:',
        'schtasks /query /fo csv > "!OUT_DIR!\\scheduled_tasks.csv" 2>&1',
        'echo 已导出 scheduled_tasks.csv',
        '',
        'echo 网络连接:',
        'netstat -ano > "!OUT_DIR!\\netstat.txt" 2>&1',
        'echo 已导出 netstat.txt',
        '',
        'echo === 5. 生成汇总报告 ===',
        '(',
        '    echo ================ 系统日志分析汇总 ================',
        '    echo 生成时间: %date% %time%',
        '    echo 计算机:   %COMPUTERNAME%',
        '    echo 用户:     %USERNAME%',
        '    echo.',
        '    echo --- Event Log 统计 ---',
        '    echo System  日志: !sys_count! 条 (Error=!sys_error!, Warn=!sys_warn!, Info=!sys_info!)',
        '    echo App     日志: !app_count! 条',
        '    echo.',
        '    echo --- 建议关注 ---',
        '    if !sys_error! gtr 0 (',
        '        echo [!] System 日志中有 !sys_error! 条 Error，请检查',
        '    ) else (',
        '        echo [√] System 无 Error 级别事件',
        '    )',
        '    if !sys_warn! gtr 10 (',
        '        echo [!] System 日志中 Warning 数量较多(!sys_warn!)，建议关注',
        '    )',
        '    echo.',
        '    echo --- 导出文件列表 ---',
        '    dir /b "!OUT_DIR!"',
        ') > "!SUMMARY!"',
        '',
        'echo.',
        'echo ============ 收集完成 ============',
        'echo 结果目录: !OUT_DIR!',
        'echo 汇总报告: !SUMMARY!',
        'echo.',
        'choice /C YN /M "打开结果目录"',
        'if errorlevel 1 start "" explorer "!OUT_DIR!"',
        'endlocal',
        'pause',
        'exit /b',
    ])
    tbl6_data = [
        ['日志类型', '来源', '收集方式', '格式', '权限', '典型内容', '体积', '关键级别', '清理建议'],
        ['System', 'Windows 内核/驱动', 'wmic ntevent', 'CSV/TXT', '普通用户', '蓝屏、服务崩溃、驱动错误', '1-10MB', 'Error/Critical', '7天后归档'],
        ['Application', '应用程序写入', 'wmic ntevent', 'CSV/TXT', '普通用户', 'App 崩溃、DLL 加载失败', '1-5MB', 'Error/Warning', '7天后归档'],
        ['Security', '安全审计', 'Get-WinEvent', 'CSV/XML', '管理员', '登录失败、权限提升、策略改变', '5-50MB', 'FailureAudit', '不能删，至少保留 90 天'],
        ['Setup', 'Windows 安装', 'wevtutil qe Setup', 'XML', '普通用户', '补丁安装、功能启用', '1-3MB', 'Info', '可清空'],
        ['ForwardedEvents', '远程转发', 'wevtutil qe', 'XML', '普通用户', '远程主机转发的事件', '不定', '全级别', '转发完删'],
        ['PowerShell', 'PowerShell 操作', 'Get-WinEvent', 'CSV', '普通用户', '脚本执行、命令历史', '1-2MB', 'Warning', '按需'],
        ['DbgPrint', '内核调试', 'windbg/kd', 'TXT', 'Debug 模式', '驱动调试输出', '不定', 'Info', '临时日志'],
        ['IIS', 'Web 服务器', 'cscript adsutil.vbs', 'W3C', 'IIS Admin', 'HTTP 请求/错误 4xx/5xx', '10-100MB', 'Error', '轮滚归档 30 天'],
        ['SQL Server', '数据库', 'SQL Server ErrorLog', 'TXT', 'SQL Admin', '连接失败、死锁、备份', '5-20MB', 'Error', '30 天归档'],
        ['Windows Update', '自动更新', 'wuauserv log', 'ETL/TXT', '管理员', '补丁下载安装失败', '1-5MB', 'Error', '可删或转储'],
        ['BITS', '后台传输', 'bitsadmin /list', 'XML', '管理员', '大文件下载/上传进度', '不定', 'Info', '下载完删'],
        ['Firewall', '防火墙日志', 'netsh advfirewall show', 'TXT', '管理员', '端口命中、拒绝连接', '10-100MB', 'Error(拒绝)', '轮滚归档'],
        ['Defender', '杀软', 'Get-MpThreatDetection', 'CSV', '普通用户', '恶意软件检测记录', '1-10MB', 'Critical/Error', '90 天'],
        ['DNS Client', 'DNS 解析', 'nltest /dsgetdc', 'TXT', '普通用户', '解析失败、超时', '不定', 'Error', '按需'],
        ['RDP', '远程桌面', 'wevtutil qe TerminalServices', 'XML', '普通用户', '登录成功/失败记录', '1-5MB', 'Failure', '90 天'],
        ['DHCP', 'IP 分配', 'wevtutil qe Microsoft-Windows-DHCP', 'XML', '普通用户', '租约分配/过期', '1-3MB', 'Error', '30 天'],
        ['PrintSpooler', '打印服务', 'wevtutil qe Microsoft-Windows-PrintSpooler', 'XML', '普通用户', '打印机错误、卡纸', '不定', 'Error', '7 天'],
        ['TaskScheduler', '计划任务', 'schtasks /query /v', 'CSV', '普通用户', '任务执行/失败', '2-10MB', 'Failure', '30 天'],
        ['W32Time', '时间同步', 'w32tm /query /log', 'TXT', '普通用户', 'NTP 同步失败', '不定', 'Error', '30 天'],
        ['USBHUB', 'USB 设备', 'wevtutil qe Microsoft-Windows-DriverFrameworks', 'XML', '普通用户', 'USB 设备插拔/故障', '不定', 'Error', '7 天'],
        ['Battery', '电源状态', 'wevtutil qe Microsoft-Windows-Kernel-Power', 'XML', '普通用户', '电池、充电状态', '不定', 'Info', '7 天'],
        ['BitLocker', '磁盘加密', 'manage-bde -status', 'TXT', '管理员', '加密/解密/恢复', '不定', 'Error', '永久'],
        ['Hyper-V', '虚拟机', 'Get-WinEvent -LogName Hyper-V-*', 'CSV', 'Hyper-V Admin', 'VM 启动/崩溃/迁移', '5-20MB', 'Error', '30 天'],
        ['Cluster', '故障转移', 'Get-WinEvent -LogName Microsoft-Windows-FailoverClustering', 'CSV', '域 Admin', '节点故障、角色转移', '10-50MB', 'Critical/Error', '90 天'],
        ['AD/DNS', 'Active Directory', 'Get-WinEvent -LogName Directory Service', 'CSV', '域 Admin', '复制失败、认证异常', '5-20MB', 'Error', '90 天'],
    ]
    t6big = Table(_wrap_table_rows(tbl6_data), colWidths=[15.4*mm, 20.8*mm, 24.7*mm, 15.4*mm, 12.1*mm, 24.7*mm, 11.0*mm, 17.6*mm, 16.5*mm])
    t6big.setStyle(TableStyle([
        ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#C0392B')),
        ('GRID', (0, 0), (-1, -1), 0.4, colors.HexColor('#D5D8DC')),
        ('ROWBACKGROUNDS', (0, 1), (-1, -1), [colors.white, colors.HexColor('#FADBD8')]),
        ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
        ('TOPPADDING', (0, 0), (-1, -1), 2),
        ('BOTTOMPADDING', (0, 0), (-1, -1), 2),
        ('LEFTPADDING',   (0, 0), (-1, -1), 6),
        ('RIGHTPADDING',  (0, 0), (-1, -1), 6),
    ]))

    ex[6] = ex[6] + [
        Spacer(1, 20),
        Paragraph('进阶项目6：日志收集器', ST_SEC_TITLE),
        Paragraph('日志收集器是故障排查的第一利器。这个脚本一次性收集系统、应用、安全三大核心事件日志，再追加 systeminfo、驱动、补丁、启动项、计划任务、网络连接这 6 大维度信息，最后自动生成汇总报告。BAT 用 wmic ntevent 做主力收集，PowerShell Get-WinEvent 做安全日志补充。', ST_BODY),
        make_code_block(code6_log),
        Spacer(1, 15),
        Paragraph('25 类 Windows 系统日志来源清单', ST_SEC_TITLE),
        t6big,
        Spacer(1, 15),
        Paragraph('Windows 事件日志系统分三层：传统 Event Log（System、Application、Security）用 wmic ntevent 可以读取；新的 Analytical/Debug 日志（如 Microsoft-Windows-*）用 PowerShell Get-WinEvent 更方便；ETW 实时追踪用 logman start/stop。BAT 最擅长前两层，第三层建议交给 PowerShell。', ST_BODY),
        Paragraph('安全日志（Security Event Log）是最敏感的一类——默认只有本地 Administrator 和域 Domain Admins 能完整读取。普通用户调用 Get-WinEvent Security 会拿到"拒绝访问"。收集脚本里必须提前判断权限，失败就跳过而不是让脚本崩溃。', ST_BODY),
        Paragraph('日志保留策略是运维核心：安全日志按合规要求至少保留 90 天，有些金融机构要求一年以上。Windows 事件查看器可以设置自动轮滚（max size + overwrite oldest），或用 wevtutil el + wevtutil epl 手动归档到 EVTX 文件——比 CSV 保留完整事件属性。', ST_BODY),
    ]

    # ============ ex[7] 第三波：一键文件夹打包工具 ============
    code7_pack = _build_code([
        '@echo off',
        'setlocal enabledelayedexpansion',
        'title 一键文件夹打包工具 v2.0',
        '',
        'rem ============================================================',
        'rem  一键文件夹打包工具',
        'rem  7z/zip 压缩 + 密码保护 + 多卷分卷',
        'rem  支持排除文件、时间戳命名、自动校验完整性',
        'rem ============================================================',
        '',
        'rem ========== 配置区 ==========',
        'set "SOURCE=%~1"',
        'if "!SOURCE!"=="" set "SOURCE=%~dp0data"',
        'set "OUTPUT_DIR=%~dp0backup"',
        'set "FMT=zip"',
        'set /a USE_7Z=0',
        'set /a USE_PASSWORD=0',
        'set "PASSWORD="',
        'set /a USE_SPLIT=0',
        'set "VOLUME_SIZE=100m"',
        'set /a CHECK_INTEGRITY=1',
        'set /a SHOW_HELP=0',
        '',
        'rem ========== 参数解析 ==========',
        ':arg_loop',
        'if "%~2"=="" goto :arg_done',
        'if /i "%~2"=="/src" (set "SOURCE=%~3" & shift & shift & goto :arg_loop)',
        'if /i "%~2"=="/out" (set "OUTPUT_DIR=%~3" & shift & shift & goto :arg_loop)',
        'if /i "%~2"=="/fmt" (set "FMT=%~3" & shift & shift & goto :arg_loop)',
        'if /i "%~2"=="/7z" (set /a USE_7Z=1 & shift & goto :arg_loop)',
        'if /i "%~2"=="/p" (set /a USE_PASSWORD=1 & set "PASSWORD=%~3" & shift & shift & goto :arg_loop)',
        'if /i "%~2"=="/split" (set /a USE_SPLIT=1 & set "VOLUME_SIZE=%~3" & shift & shift & goto :arg_loop)',
        'if /i "%~2"=="/skip" (set /a CHECK_INTEGRITY=0 & shift & goto :arg_loop)',
        'if /i "%~2"=="/?" (set /a SHOW_HELP=1 & shift & goto :arg_loop)',
        'shift',
        'goto :arg_loop',
        ':arg_done',
        '',
        'if !SHOW_HELP! equ 1 goto :show_help',
        '',
        'rem ========== 检查源目录 ==========',
        'if not exist "!SOURCE!" (',
        '    echo [错误] 源目录不存在: !SOURCE!',
        '    echo 用法: pack.bat /src C:\\Data /out D:\\Backup /fmt zip',
        '    pause',
        '    exit /b 1',
        ')',
        '',
        'rem ========== 7z 检测 ==========',
        'where 7z >nul 2>&1',
        'if !errorlevel! equ 0 set /a HAS_7Z=1 else set /a HAS_7Z=0',
        '',
        'if !USE_7Z! equ 1 if !HAS_7Z! equ 0 (',
        '    echo [警告] 未检测到 7z，改用 PowerShell Compress-Archive',
        '    set /a USE_7Z=0',
        ')',
        '',
        'rem ========== 生成时间戳 ==========',
        'set "TS=%date:~0,4%%date:~5,2%%date:~8,2%_%time:~0,2%%time:~3,2%%time:~6,2%"',
        'set "TS=!TS: =0!"',
        'for %%d in ("!SOURCE!") do set "NAME=%%~nd"',
        'set "OUT_NAME=!NAME!_!TS!"',
        '',
        'rem ========== 创建输出目录 ==========',
        'if not exist "!OUTPUT_DIR!" mkdir "!OUTPUT_DIR!" 2>nul',
        '',
        'echo.',
        'echo === 文件夹打包工具 ===',
        'echo 源目录:     !SOURCE!',
        'echo 输出目录:   !OUTPUT_DIR!',
        'echo 压缩格式:   !FMT!  ^(7z=!USE_7Z!^)',
        'echo 密码保护:   !USE_PASSWORD!',
        'echo 多卷分卷:   !USE_SPLIT! ^(大小=!VOLUME_SIZE!^)',
        'echo 完整性校验: !CHECK_INTEGRITY!',
        'echo 输出名称:   !OUT_NAME!',
        'echo.',
        '',
        'rem ========== 开始压缩 ==========',
        'echo 正在压缩...',
        'echo.',
        '',
        'set /a start_tick=%time:~6,2%+%time:~3,2%*60+%time:~0,2%*3600',
        '',
        'if !USE_7Z! equ 1 goto :compress_7z',
        '',
        ':compress_zip',
        'set "OUT_FILE=!OUTPUT_DIR!\\!OUT_NAME!.zip"',
        'if !USE_PASSWORD! equ 1 (',
        '    if !HAS_7Z! equ 1 (',
        '        7z a -tzip -p"!PASSWORD!" "!OUT_FILE!" "!SOURCE!" -mx=5',
        '    ) else (',
        '        echo [提示] PowerShell Compress-Archive 不支持密码，改用 AES-256 ZIP 请安装 7-Zip',
        '        powershell -Command "Compress-Archive -Path \'!SOURCE!\\*\' -DestinationPath \'!OUT_FILE!\' -CompressionLevel Optimal"',
        '    )',
        ') else (',
        '    if !USE_SPLIT! equ 1 (',
        '        if !HAS_7Z! equ 1 (',
        '            7z a -tzip -v!VOLUME_SIZE! "!OUT_FILE!" "!SOURCE!" -mx=5',
        '        ) else (',
        '            echo [提示] 分卷压缩需要 7-Zip，已跳过分卷',
        '            powershell -Command "Compress-Archive -Path \'!SOURCE!\\*\' -DestinationPath \'!OUT_FILE!\' -CompressionLevel Optimal"',
        '        )',
        '    ) else (',
        '        powershell -Command "Compress-Archive -Path \'!SOURCE!\\*\' -DestinationPath \'!OUT_FILE!\' -CompressionLevel Optimal"',
        '    )',
        ')',
        'goto :compress_done',
        '',
        ':compress_7z',
        'set "OUT_FILE=!OUTPUT_DIR!\\!OUT_NAME!.7z"',
        'set "7z_args=a -t7z -mx=5"',
        'if !USE_PASSWORD! equ 1 set "7z_args=!7z_args! -p!PASSWORD!"',
        'if !USE_SPLIT! equ 1 set "7z_args=!7z_args! -v!VOLUME_SIZE!"',
        '7z !7z_args! "!OUT_FILE!" "!SOURCE!"',
        'goto :compress_done',
        '',
        ':compress_done',
        'set /a end_tick=%time:~6,2%+%time:~3,2%*60+%time:~0,2%*3600',
        'set /a elapsed=end_tick-start_tick',
        'if !elapsed! lss 0 set /a elapsed+=86400',
        '',
        'echo.',
        'echo 压缩完成！耗时 !elapsed! 秒',
        '',
        'rem ========== 完整性校验 ==========',
        'if !CHECK_INTEGRITY! equ 1 (',
        '    echo.',
        '    echo === 完整性校验 ===',
        '    if !HAS_7Z! equ 1 (',
        '        if !USE_SPLIT! equ 1 (',
        '            7z t "!OUT_FILE!.001" 2>nul || 7z t "!OUT_FILE!.part01" 2>nul',
        '        ) else (',
        '            7z t "!OUT_FILE!"',
        '        )',
        '    ) else (',
        '        echo 用 certutil 生成 SHA256:',
        '        certutil -hashfile "!OUT_FILE!" SHA256 | findstr /v certutil | findstr /v ":"',
        '    )',
        ')',
        '',
        'rem ========== 显示结果 ==========',
        'echo.',
        'echo === 输出文件 ===',
        'dir /b "!OUTPUT_DIR!\\!OUT_NAME!*" 2>nul',
        'echo.',
        'choice /C YN /M "打开输出目录"',
        'if errorlevel 1 start "" explorer "!OUTPUT_DIR!"',
        'endlocal',
        'exit /b',
        '',
        ':show_help',
        'echo.',
        'echo 用法: pack.bat /src ^<源目录^> [选项]',
        'echo.',
        'echo 选项:',
        'echo   /src ^<path^>       要打包的源目录',
        'echo   /out ^<path^>       输出目录 (默认: backup)',
        'echo   /fmt zip^|7z       压缩格式 (默认 zip)',
        'echo   /7z                强制使用 7-Zip',
        'echo   /p ^<password^>     设置压缩密码',
        'echo   /split ^<size^>    分卷大小 (例: 100m, 1g)',
        'echo   /skip              跳过完整性校验',
        'echo   /?                 显示帮助',
        'echo.',
        'echo 示例:',
        'echo   pack.bat /src C:\\Project /out D:\\Backup',
        'echo   pack.bat /src C:\\Data /7z /p secret123',
        'echo   pack.bat /src C:\\BigFolder /split 500m',
        'pause',
        'exit /b',
    ])
