    ex[10] = ex[10] + [
        Spacer(1, 20),
        Paragraph('进阶项目10：批量主机连通性扫描', ST_SEC_TITLE),
        Paragraph('这个扫描器是 BAT 多线程技术的集大成者：start /b 并发 ping、IP 段生成、CIDR 解析、失败重试、CSV 导出、并发数控制（防止创建过多 cmd.exe）。核心技巧是用临时文件 !IP_LIST!.ok 收集在线主机、!IP_LIST!.result 收集原始 ping 输出，最后用 findstr /c:"TTL" 过滤出成功记录。', ST_BODY),
        make_code_block(code10_ping),
        Spacer(1, 15),
        Paragraph('25 种连通性扫描场景实现方案', ST_SEC_TITLE),
        t10big,
        Spacer(1, 15),
        Paragraph('BAT 并发 ping 的核心瓶颈是 cmd.exe 进程创建和控制。start /b 可以后台启动子 cmd.exe 执行 ping，但无法精确控制并发数——脚本里用 tasklist | find /c "cmd.exe" 统计当前 cmd 进程数，超过 PARALLEL 阈值就暂停一会儿。这个方式不够精确但对几百台主机的扫描够用了。', ST_BODY),
        Paragraph('ping 结果解析的标准化方式是 findstr /c:"TTL"——无论 ping 是中文还是英文、成功输出长什么样，成功响应里一定有 TTL= 字样。失败则返回 "请求超时" 或 "Destination host unreachable"。findstr 找到 TTL 说明在线，找不到就离线。', ST_BODY),
        Paragraph('超时参数 -w 500 最实用——500 毫秒足够局域网 ping 到，又不会让坏 IP 等太久。超时加超时是 1 秒内一个 IP。254 台主机如果串行要 254 秒，用 50 并发大概 5-10 秒完成。但注意并发会让目标主机收到大量 ICMP——不要对生产大网段高频使用。', ST_BODY),
    ]

    # ============ ex[11] 第三波：完整的 BAT+PowerShell 混合工具箱 ============
    code11_hybrid = _build_code([
        '@echo off',
        'setlocal enabledelayedexpansion',
        'title BAT + PowerShell 混合工具箱 - 15 个常用场景',
        'color 09',
        '',
        'rem ============================================================',
        'rem  BAT + PowerShell 混合工具箱',
        'rem BAT 做流程控制和用户交互',
        'rem PowerShell 做复杂操作（.NET 库、WMI、JSON、加密等）',
        'rem ============================================================',
        '',
        ':MENU',
        'cls',
        'echo.',
        'echo   ================================================',
        'echo      BAT + PowerShell 混合工具箱 (15 in 1)',
        'echo   ================================================',
        'echo.',
        'echo   [ 1]  求平方根/数学函数        [ 2]  JSON 解析',
        'echo   [ 3]  哈希文件 (SHA256)        [ 4]  Base64 编解码',
        'echo   [ 5]  加密/解密字符串          [ 6]  正则表达式匹配',
        'echo   [ 7]  下载 HTTPS 文件          [ 8]  解压 ZIP/7Z',
        'echo   [ 9]  XML 解析                [10]  Excel 操作',
        'echo   [11]  发送邮件 (SMTP)         [12]  HTTP REST API',
        'echo   [13]  Windows 弹窗/Toast      [14]  系统服务管理',
        'echo   [15]  截图/图像处理',
        'echo   [ 0]  退出',
        'echo.',
        'set /p "choice=选择: "',
        '',
        'if "!choice!"=="0" goto :END',
        'if "!choice!"=="1" call :demo_sqrt',
        'if "!choice!"=="2" call :demo_json',
        'if "!choice!"=="3" call :demo_hash',
        'if "!choice!"=="4" call :demo_b64',
        'if "!choice!"=="5" call :demo_crypto',
        'if "!choice!"=="6" call :demo_regex',
        'if "!choice!"=="7" call :demo_download',
        'if "!choice!"=="8" call :demo_extract',
        'if "!choice!"=="9" call :demo_xml',
        'if "!choice!"=="10" call :demo_excel',
        'if "!choice!"=="11" call :demo_email',
        'if "!choice!"=="12" call :demo_rest',
        'if "!choice!"=="13" call :demo_toast',
        'if "!choice!"=="14" call :demo_service',
        'if "!choice!"=="15" call :demo_image',
        '',
        'pause',
        'goto :MENU',
        ':END',
        'exit /b',
        '',
        ':demo_sqrt',
        'echo.',
        'echo [1] PowerShell 数学函数',
        'set /p num=输入一个数字: ',
        'for /f "delims=" %%r in (\'powershell -Command "[math]::Sqrt(!num!)"\') do echo !num! 的平方根 = %%r',
        'for /f "delims=" %%r in (\'powershell -Command "[math]::Pow(!num!, 3)"\') do echo !num! 的立方 = %%r',
        'for /f "delims=" %%r in (\'powershell -Command "[math]::PI"\') do echo PI = %%r',
        'exit /b',
        '',
        ':demo_json',
        'echo.',
        'echo [2] PowerShell JSON 解析',
        'echo {"name":"张三","age":25,"skills":["BAT","PS","Python"]} | powershell -Command "$input | ConvertFrom-Json | ForEach-Object { $_.name + \' - \' + $_.age + \'岁, 会 \' + ($_.skills -join \', \') }"',
        'exit /b',
        '',
        ':demo_hash',
        'echo.',
        'echo [3] PowerShell 文件哈希 (SHA256)',
        'echo !random! test content > hash_test.txt',
        'powershell -Command "Get-FileHash -Path \'hash_test.txt\' -Algorithm SHA256 | Select-Object Hash, Path"',
        'del hash_test.txt',
        'exit /b',
        '',
        ':demo_b64',
        'echo.',
        'echo [4] PowerShell Base64 编解码',
        'echo 原始字符串: Hello BAT + PowerShell',
        'for /f "delims=" %%e in (\'powershell -Command "[Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes(\'Hello BAT + PowerShell\'))"\') do echo 编码后: %%e',
        'for /f "delims=" %%d in (\'powershell -Command "[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(\'SGVsbG8gQkFUICsgUG93ZXJTaGVsbA==\'))"\') do echo 解码后: %%d',
        'exit /b',
        '',
        ':demo_crypto',
        'echo.',
        'echo [5] PowerShell AES-256 加密',
        'echo 加密前: mysecretpassword',
        'set /p pwd=输入加密密码(至少16字符): ',
        'powershell -Command "$aes=[System.Security.Cryptography.Aes]::Create(); $aes.Key=[System.Text.Encoding]::UTF8.GetBytes(\'!pwd!\'.PadRight(32).Substring(0,32)); $aes.GenerateIV(); $enc=$aes.CreateEncryptor(); $encBytes=$enc.TransformFinalBlock([System.Text.Encoding]::UTF8.GetBytes(\'mysecretpassword\'),0,20); echo ([Convert]::ToBase64String($encBytes))"',
        'exit /b',
        '',
        ':demo_regex',
        'echo.',
        'echo [6] PowerShell 正则表达式',
        'echo IP 地址列表: 192.168.1.1, 10.0.0.1, 无效: 999.999.999.999',
        'echo 192.168.1.1 10.0.0.1 999.999.999.999 | powershell -Command "echo \'192.168.1.1 10.0.0.1 999.999.999.999\' | Select-String -Pattern \'\\b(?:\\d{1,3}\\.){3}\\d{1,3}\\b\' -AllMatches | ForEach-Object { $_.Matches.Value }"',
        'exit /b',
        '',
        ':demo_download',
        'echo.',
        'echo [7] PowerShell 下载 HTTPS 文件',
        'echo 正在下载测试文件...',
        'powershell -Command "try { Invoke-WebRequest -Uri \'https://httpbin.org/get\' -OutFile \'download_test.json\' -TimeoutSec 10; Write-Host \'下载成功\'; Get-Content download_test.json | Select-Object -First 5 } catch { Write-Host \'下载失败或无网络\' }"',
        'del download_test.json 2>nul',
        'exit /b',
        '',
        ':demo_extract',
        'echo.',
        'echo [8] PowerShell 解压',
        'echo 先用 Compress-Archive 做个测试 ZIP...',
        'echo test file content > zip_test.txt',
        'powershell -Command "Compress-Archive -Path \'zip_test.txt\' -DestinationPath \'zip_test.zip\'"',
        'powershell -Command "Expand-Archive -Path \'zip_test.zip\' -DestinationPath \'zip_test_out\' -Force"',
        'echo 解压结果:',
        'type zip_test_out\\zip_test.txt',
        'del zip_test.txt zip_test.zip & rmdir /s /q zip_test_out',
        'exit /b',
        '',
        ':demo_xml',
        'echo.',
        'echo [9] PowerShell XML 解析',
        '(',
        'echo ^<root^>',
        'echo   ^<app name="MyBat" version="2.0"^>',
        'echo     ^<author^>BAT Master^</author^>',
        'echo     ^<items^>',
        'echo       ^<item id="1"^>First^</item^>',
        'echo       ^<item id="2"^>Second^</item^>',
        'echo     ^</items^>',
        'echo   ^</app^>',
        'echo ^</root^>',
        ') > xml_test.xml',
        'powershell -Command "$xml=[xml](Get-Content xml_test.xml); $xml.root.app | ForEach-Object { Write-Host $_.name - $_.version - by $_.author; foreach($i in $_.items.item){Write-Host \'  Item:\' $i.id $i.\'#text\' } }"',
        'del xml_test.xml',
        'exit /b',
        '',
        ':demo_excel',
        'echo.',
        'echo [10] PowerShell Excel 操作 (需要 Excel 已安装)',
        'powershell -Command "try { $excel=New-Object -ComObject Excel.Application; $excel.Visible=$false; $wb=$excel.Workbooks.Add(); $ws=$wb.Sheets.Item(1); $ws.Cells.Item(1,1)=\'姓名\'; $ws.Cells.Item(1,2)=\'年龄\'; $ws.Cells.Item(2,1)=\'张三\'; $ws.Cells.Item(2,2)=25; $wb.SaveAs(\'excel_test.xlsx\'); $excel.Quit(); Write-Host \'Excel 创建成功: excel_test.xlsx\' } catch { Write-Host \'Excel COM 调用失败 (可能没装 Excel)\' }"',
        'del excel_test.xlsx 2>nul',
        'exit /b',
        '',
        ':demo_email',
        'echo.',
        'echo [11] PowerShell SMTP 发送邮件',
        'echo 需要修改下面的 SMTP 配置才能工作：',
        'echo   $smtp = smtp.example.com',
        'echo   $from = sender@example.com',
        'echo   $to = receiver@example.com',
        'powershell -Command "$smtp=\'smtp.example.com\'; $from=\'sender@example.com\'; $to=\'receiver@example.com\'; Send-MailMessage -SmtpServer $smtp -From $from -To $to -Subject \'来自 BAT+PS 的测试邮件\' -Body \'如果收到说明 SMTP 配置正确\'" 2>&1',
        'exit /b',
        '',
        ':demo_rest',
        'echo.',
        'echo [12] PowerShell HTTP REST API',
        'echo 请求 httpbin.org API...',
        'powershell -Command "try { $r=Invoke-RestMethod -Uri \'https://httpbin.org/user-agent\' -TimeoutSec 10; Write-Host \'UserAgent:\' $r.{\'user-agent\'} } catch { Write-Host \'网络不可用\' }"',
        'exit /b',
        '',
        ':demo_toast',
        'echo.',
        'echo [13] PowerShell Windows 弹窗/Toast',
        'powershell -Command "Add-Type -AssemblyName System.Windows.Forms; [System.Windows.Forms.MessageBox]::Show(\'这是一个 BAT + PowerShell 弹窗\\n\\n标题: 混合工具箱\', \'BAT + PowerShell Demo\', \'OK\', \'Information\')"',
        'exit /b',
        '',
        ':demo_service',
        'echo.',
        'echo [14] PowerShell 服务管理',
        'powershell -Command "Get-Service | Where-Object {$_.Status -eq \'Running\'} | Select-Object -First 10 Name, DisplayName, Status | Format-Table -AutoSize"',
        'exit /b',
        '',
        ':demo_image',
        'echo.',
        'echo [15] PowerShell 图像处理',
        'echo 用 System.Drawing 创建一个小图片...',
        'powershell -Command "Add-Type -AssemblyName System.Drawing; $b=New-Object Drawing.Bitmap(200,100); $g=[Drawing.Graphics]::FromImage($b); $g.Clear([Drawing.Color]::LightBlue); $font=New-Object Drawing.Font(\'Arial\',16); $g.DrawString(\'Hello BAT+PS!\',$font,[Drawing.Brushes]::Black,20,40); $b.Save(\'image_test.png\',[Drawing.Imaging.ImageFormat]::Png); $g.Dispose(); $b.Dispose(); Write-Host \'图片已生成: image_test.png\'"',
        'del image_test.png 2>nul',
        'exit /b',
    ])
