        ['临时文件清理', '%TEMP%', '按扩展名', '*.tmp,*.bak', '立即删', '无', '直接删除', '>> cleanup.log', 'schtasks 每天', '排除系统目录', 'cleanmgr'],
        ['桌面整理', 'Desktop', 'Category/YYYY-MM-DD', '扩展名 8 类', '每次清理', '>1KB 过滤', 'move /y 覆盖', '>> logfile', '手动/定时', '保留 .lnk .bat', '本脚本'],
        ['下载整理', 'Downloads', 'Category/YYYY-MM-DD', '扩展名 8 类', '每周清理', '>1KB 过滤', '重名加时间戳', '>> logfile', 'schtasks 每周', '排除正在下载', '本脚本+文件锁'],
