    t13big = Table(_wrap_table_rows(tbl13_data), colWidths=[14.0*mm, 12.5*mm, 16.0*mm, 12.5*mm, 12.5*mm, 11.0*mm, 12.5*mm, 9.0*mm, 11.0*mm, 16.0*mm, 15.0*mm, 16.0*mm])
