        ['UAC', 'EnableLUA', '1 (启用)', '静默执行恶意软件', 'HIGH', '每月', 'reg add ... EnableLUA 1', '计算机\\管理模板\\Windows\\本地安全策略', 'CIS 3.1', '可以', '不影响正常使用'],
        ['防火墙', 'netsh advfirewall', 'ON', '暴露所有端口', 'HIGH', '每天', 'netsh advfirewall set allprofiles state on', '计算机\\管理模板\\Windows Defender 防火墙', 'CIS 3.3', '可以', '企业需组策略'],
