        ['BitLocker', 'manage-bde -status', '完全加密', '硬盘丢失/数据泄露', 'CRITICAL', '每月', 'manage-bde -on C:', '计算机\\管理模板\\Windows 组件\\BitLocker', 'CIS 2.2', '需要 TPM', '影响性能'],
